const e="hsk",t=4,n=[{num:1,title:"简单的爱情",points:[{id:"4.1.1",name:"不仅……，也/还/而且……",pinyin:"bùjǐn ... yě/hái/érqiě ...",type:"递进复句",explainEn:"Use 不仅…还/而且… for “not only…, but also…”.",structure:"不仅 + A，也/还/而且 + B",examples:[{zh:"他不仅会说汉语，还会说英语。",en:"He can speak not only Chinese but also English."},{zh:"这个地方不仅漂亮，而且很安静。",en:"This place is not only beautiful but also quiet."},{zh:"她不仅学习认真，也很热情。",en:"She not only studies hard but is also warm-hearted."}],exercises:[{q:"填空：他___会游泳，还会打篮球。",a:"不仅",instr:"填空",instrEn:"Fill in the blank",body:"他___会游泳，还会打篮球。"},{q:"翻译：This place is not only beautiful but also quiet.",a:"这个地方不仅漂亮，而且很安静。",instr:"翻译",instrEn:"Translate",body:"This place is not only beautiful but also quiet."},{q:"用“不仅……而且……”连接：他很聪明。他很努力。",a:"他不仅很聪明，而且很努力。"}],note:"两个分句主语相同时，“不仅”一般放在主语后。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"When both clauses share a subject, 不仅 usually goes after the subject.",typeEn:"Progressive clause",tier:"HSK4教材内"},{id:"4.1.2",name:"副词“从来”",pinyin:"cónglái",type:"副词",explainEn:"Use 从来 with 不/没 to mean “never / always not”.",structure:"从来 + 不 + V；从来 + 没 + V + 过",examples:[{zh:"我从来不喝酒。",en:"I never drink alcohol."},{zh:"他从来没迟到过。",en:"He has never been late."},{zh:"她从来不说别人坏话。",en:"She never says bad things about others."}],exercises:[{q:"填空：我___不抽烟。",a:"从来",instr:"填空",instrEn:"Fill in the blank",body:"我___不抽烟。"},{q:"翻译：He has never been late.",a:"他从来没迟到过。",instr:"翻译",instrEn:"Translate",body:"He has never been late."},{q:"改写：我没去过国外。（用“从来”）",a:"我从来没去过国外。",instr:"改写",instrEn:"Rewrite",body:"我没去过国外。（用“从来”）"}],note:"“从来”最常和否定形式一起使用。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"从来 is most often used with a negative.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.1.3",name:"“刚”和“刚才”",pinyin:"gāng / gāngcái",type:"时间表达",explainEn:"刚 means “just” before a verb. 刚才 means “just now” and can be used as a time word.",structure:"刚 + V；刚才 + 句子",examples:[{zh:"我刚到家。",en:"I just got home."},{zh:"刚才老师给我打电话了。",en:"The teacher called me just now."},{zh:"他刚吃完饭。",en:"He just finished eating."}],exercises:[{q:"填空：我___到公司。",a:"刚",instr:"填空",instrEn:"Fill in the blank",body:"我___到公司。"},{q:"填空：___他还在这里。",a:"刚才",instr:"填空",instrEn:"Fill in the blank",body:"___他还在这里。"},{q:"翻译：He just finished eating.",a:"他刚吃完饭。",instr:"翻译",instrEn:"Translate",body:"He just finished eating."}],note:"“刚才”可以放在主语前；“刚”一般紧靠动词。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"刚才 can go before the subject; 刚 stays close to the verb.",typeEn:"Time",tier:"HSK4教材内"},{id:"4.1.4",name:"即使……，也……",pinyin:"jíshǐ ... yě ...",type:"让步复句",explainEn:"Use 即使…也… for “even if…, still…”.",structure:"即使 + 条件，也 + 结果",examples:[{zh:"即使下雨，我也要去。",en:"Even if it rains, I will still go."},{zh:"即使很忙，他也每天运动。",en:"Even if he is busy, he exercises every day."},{zh:"即使你不同意，我也会试试。",en:"Even if you disagree, I will still try."}],exercises:[{q:"填空：___下雨，我___要去。",a:"即使；也",instr:"填空",instrEn:"Fill in the blank",body:"___下雨，我___要去。"},{q:"翻译：Even if he is busy, he still studies.",a:"即使他很忙，他也学习。",instr:"翻译",instrEn:"Translate",body:"Even if he is busy, he still studies."},{q:"连接：很难。我也要继续。",a:"即使很难，我也要继续。",instr:"连接",instrEn:"Join the sentences",body:"很难。我也要继续。"}],note:"前面是假设条件，后面的结果不受这个条件影响。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The first part is a hypothetical; the result holds regardless of it.",typeEn:"Concessive clause",tier:"HSK4教材内"},{id:"4.1.5",name:"“（在）……上”表示方面",pinyin:"(zài) ... shàng",type:"介词结构",explainEn:"Use 在…上 to mean “in terms of / in the area of…”.",structure:"在 + 名词 + 上",examples:[{zh:"他在工作上很认真。",en:"He is very serious at work."},{zh:"我们在学习上互相帮助。",en:"We help each other in our studies."},{zh:"这个办法在时间上更方便。",en:"This method is more convenient in terms of time."}],exercises:[{q:"填空：他___工作___很认真。",a:"在；上",instr:"填空",instrEn:"Fill in the blank",body:"他___工作___很认真。"},{q:"翻译：We help each other in our studies.",a:"我们在学习上互相帮助。",instr:"翻译",instrEn:"Translate",body:"We help each other in our studies."},{q:"选择：“在学习（上 / 下）”表示“在学习方面”。",a:"上",instr:"选择",instrEn:"Choose",body:"“在学习（上 / 下）”表示“在学习方面”。"}],note:"这里的“上”不是方位，而是表示某个方面。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Here 上 isn't a location; it marks an aspect/respect.",typeEn:"Prep. phrase",tier:"HSK4教材内"}]},{num:2,title:"真正的朋友",points:[{id:"4.2.1",name:"副词“正好”",pinyin:"zhènghǎo",type:"副词",explainEn:"Use 正好 to mean “just right / exactly / just in time”.",structure:"正好 + V/Adj；数量 + 正好",examples:[{zh:"你来得正好。",en:"You came at just the right time."},{zh:"这件衣服大小正好。",en:"This clothing fits just right."},{zh:"我正好有两个苹果。",en:"I happen to have exactly two apples."}],exercises:[{q:"填空：你来得___。",a:"正好",instr:"填空",instrEn:"Fill in the blank",body:"你来得___。"},{q:"翻译：This size is just right.",a:"这个大小正好。",instr:"翻译",instrEn:"Translate",body:"This size is just right."},{q:"补全：我___也要去，我们一起吧。",a:"正好",instr:"补全",instrEn:"Complete the sentence",body:"我___也要去，我们一起吧。"}],note:"“正好”表示时间、数量或情况非常合适。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"正好 means a time, amount or situation fits perfectly.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.2.2",name:"“差不多”和“几乎”",pinyin:"chàbuduō / jīhū",type:"副词/形容词",explainEn:"差不多 means “almost / about the same”. 几乎 means “almost, nearly”.",structure:"差不多 + Adj/数量；几乎 + V/都",examples:[{zh:"我们两个人差不多高。",en:"We are about the same height."},{zh:"现在差不多十点了。",en:"It is almost ten now."},{zh:"他几乎每天都运动。",en:"He exercises almost every day."}],exercises:[{q:"填空：我们俩___高。",a:"差不多",instr:"填空",instrEn:"Fill in the blank",body:"我们俩___高。"},{q:"填空：他___每天都来。",a:"几乎",instr:"填空",instrEn:"Fill in the blank",body:"他___每天都来。"},{q:"翻译：It is almost ten.",a:"现在差不多十点了。",instr:"翻译",instrEn:"Translate",body:"It is almost ten."}],note:"“差不多”还能表示两者接近；“几乎”更常修饰动作或范围。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'差不多 can mean "close/similar"; 几乎 more often modifies an action or scope.',typeEn:"Adverb / Adjective",tier:"HSK4教材内"},{id:"4.2.3",name:"尽管……，但是/可是/还是……",pinyin:"jǐnguǎn ... dànshì/kěshì/háishi ...",type:"转折复句",explainEn:"Use 尽管…但是/可是/还是… for “although…, still/but…”.",structure:"尽管 + 事实，但是/可是/还是 + 结果",examples:[{zh:"尽管很累，他还是去上班了。",en:"Although he was tired, he still went to work."},{zh:"尽管下雨，但是我们还是出门了。",en:"Although it rained, we still went out."},{zh:"尽管这本书很难，可是我很喜欢。",en:"Although this book is difficult, I like it very much."}],exercises:[{q:"填空：___很累，他___继续工作。",a:"尽管；还是",instr:"填空",instrEn:"Fill in the blank",body:"___很累，他___继续工作。"},{q:"翻译：Although the book is difficult, I like it.",a:"尽管这本书很难，可是我很喜欢。",instr:"翻译",instrEn:"Translate",body:"Although the book is difficult, I like it."},{q:"连接：天气很冷。我们还是出去跑步。",a:"尽管天气很冷，我们还是出去跑步。",instr:"连接",instrEn:"Join the sentences",body:"天气很冷。我们还是出去跑步。"}],note:"“尽管”说的是已经存在的事实，后面出现与预期不同的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"尽管 states an existing fact, followed by an unexpected result.",typeEn:"Adversative clause",tier:"HSK4教材内"},{id:"4.2.4",name:"副词“却”表示转折",pinyin:"què",type:"副词",explainEn:"Use 却 to show an unexpected contrast: “but / yet”.",structure:"主语 + 却 + 谓语",examples:[{zh:"他很累，却不想休息。",en:"He is tired, but he does not want to rest."},{zh:"我认识他，他却不认识我。",en:"I know him, but he does not know me."},{zh:"天气很冷，她却穿得很少。",en:"It is cold, yet she is wearing very little."}],exercises:[{q:"填空：他很忙，___每天都运动。",a:"却",instr:"填空",instrEn:"Fill in the blank",body:"他很忙，___每天都运动。"},{q:"翻译：I know him, but he does not know me.",a:"我认识他，他却不认识我。",instr:"翻译",instrEn:"Translate",body:"I know him, but he does not know me."},{q:"排序：却 / 她 / 不 / 生气",a:"她却不生气。",instr:"排序",instrEn:"Reorder the words",body:"却 / 她 / 不 / 生气"}],note:"“却”一般放在第二个分句的主语后、谓语前。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"却 usually sits after the subject and before the predicate of the second clause.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.2.5",name:"连词“而”",pinyin:"ér",type:"连词",explainEn:"Use 而 to connect two parts, often with contrast or addition. It is more written/formal.",structure:"A，而 + B",examples:[{zh:"他喜欢安静，而我喜欢热闹。",en:"He likes quiet places, while I like lively ones."},{zh:"这个方法简单而有效。",en:"This method is simple and effective."},{zh:"她年轻而有经验。",en:"She is young and experienced."}],exercises:[{q:"填空：他喜欢茶，___我喜欢咖啡。",a:"而",instr:"填空",instrEn:"Fill in the blank",body:"他喜欢茶，___我喜欢咖啡。"},{q:"翻译：This method is simple and effective.",a:"这个方法简单而有效。",instr:"翻译",instrEn:"Translate",body:"This method is simple and effective."},{q:"选择：“年轻___有经验”用（而 / 吗）。",a:"而",instr:"选择",instrEn:"Choose",body:"“年轻___有经验”用（而 / 吗）。"}],note:"“而”比“但是、和”更书面，具体意思要看上下文。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"而 is more formal than 但是/和; its exact sense depends on context.",typeEn:"Conjunction",tier:"HSK4教材内"}]},{num:3,title:"经理对我印象不错",points:[{id:"4.3.1",name:"程度副词“挺”",pinyin:"tǐng",type:"副词",explainEn:"Use 挺 + adjective + 的 to mean “quite / pretty”.",structure:"挺 + 形容词 +（的）",examples:[{zh:"这个工作挺有意思的。",en:"This job is quite interesting."},{zh:"今天挺冷的。",en:"It is pretty cold today."},{zh:"他人挺好的。",en:"He is quite nice."}],exercises:[{q:"填空：今天___冷的。",a:"挺",instr:"填空",instrEn:"Fill in the blank",body:"今天___冷的。"},{q:"翻译：This job is quite interesting.",a:"这个工作挺有意思的。",instr:"翻译",instrEn:"Translate",body:"This job is quite interesting."},{q:"排序：挺 / 他 / 好 / 的",a:"他挺好的。",instr:"排序",instrEn:"Reorder the words",body:"挺 / 他 / 好 / 的"}],note:"口语中很常见，句尾常加“的”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Very common in speech, often ending with 的.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.3.2",name:"副词“本来”",pinyin:"běnlái",type:"副词",explainEn:"Use 本来 for an original plan, situation, or fact: “originally”.",structure:"本来 + 情况/计划",examples:[{zh:"我本来想去北京。",en:"I originally wanted to go to Beijing."},{zh:"他本来今天休息。",en:"He was originally off today."},{zh:"这件事本来很简单。",en:"This was originally very simple."}],exercises:[{q:"填空：我___想坐地铁。",a:"本来",instr:"填空",instrEn:"Fill in the blank",body:"我___想坐地铁。"},{q:"翻译：This was originally very simple.",a:"这件事本来很简单。",instr:"翻译",instrEn:"Translate",body:"This was originally very simple."},{q:"补全：他___不想买，后来改变了主意。",a:"本来",instr:"补全",instrEn:"Complete the sentence",body:"他___不想买，后来改变了主意。"}],note:"“本来”强调原来的计划或情况，后来可能发生变化。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"本来 stresses the original plan/situation, which may later change.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.3.3",name:"“另、另外、其他”",pinyin:"lìng / lìngwài / qítā",type:"代词/副词",explainEn:"另 means “another” before a measure word/noun. 另外 means “another / besides”. 其他 means “other”.",structure:"另 + 量词 + 名词；另外 + 句子/名词；其他 + 名词",examples:[{zh:"我们再找另一个办法。",en:"Let us find another way."},{zh:"另外，我还有一个问题。",en:"Besides, I have another question."},{zh:"其他人都到了。",en:"All the other people have arrived."}],exercises:[{q:"填空：我们换___一个地方。",a:"另",instr:"填空",instrEn:"Fill in the blank",body:"我们换___一个地方。"},{q:"翻译：Besides, I have another question.",a:"另外，我还有一个问题。",instr:"翻译",instrEn:"Translate",body:"Besides, I have another question."},{q:"填空：___学生都到了。",a:"其他",instr:"填空",instrEn:"Fill in the blank",body:"___学生都到了。"}],note:"“另”通常不能单独使用；“另外”可以连接补充信息。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"另 usually can't stand alone; 另外 can introduce extra information.",typeEn:"Pronoun / Adverb",tier:"HSK4教材内"},{id:"4.3.4",name:"“首先……其次……”表示顺序",pinyin:"shǒuxiān ... qícì ...",type:"顺序结构",explainEn:"Use 首先…其次… to organize points: “first…, second…”.",structure:"首先 + 第一点；其次 + 第二点",examples:[{zh:"首先要认真听，其次要多练习。",en:"First listen carefully; second, practice more."},{zh:"首先谢谢大家，其次我想说一下计划。",en:"First, thank you; second, I want to talk about the plan."},{zh:"买房首先看位置，其次看价格。",en:"When buying a home, first look at location, then price."}],exercises:[{q:"填空：___要准备好，___要按时到。",a:"首先；其次",instr:"填空",instrEn:"Fill in the blank",body:"___要准备好，___要按时到。"},{q:"翻译：First listen carefully; second, practice more.",a:"首先要认真听，其次要多练习。",instr:"翻译",instrEn:"Translate",body:"First listen carefully; second, practice more."},{q:"用“首先……其次……”说两个学习建议。",a:"首先多听，其次多说。"}],note:"常用于比较正式地列出两点或多点。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Used to list two or more points fairly formally.",typeEn:"Sequence structure",tier:"HSK4教材内"},{id:"4.3.5",name:"不管……，都/也……",pinyin:"bùguǎn ... dōu/yě ...",type:"条件复句",explainEn:"Use 不管…都/也… for “no matter…, always/still…”.",structure:"不管 + 疑问形式/选择，都/也 + 结果",examples:[{zh:"不管多忙，他都坚持运动。",en:"No matter how busy he is, he keeps exercising."},{zh:"不管你去不去，我都要去。",en:"Whether you go or not, I will go."},{zh:"不管发生什么，我都支持你。",en:"No matter what happens, I support you."}],exercises:[{q:"填空：___多累，他___学习。",a:"不管；都",instr:"填空",instrEn:"Fill in the blank",body:"___多累，他___学习。"},{q:"翻译：No matter what happens, I support you.",a:"不管发生什么，我都支持你。",instr:"翻译",instrEn:"Translate",body:"No matter what happens, I support you."},{q:"连接：下不下雨。我们都出发。",a:"不管下不下雨，我们都出发。",instr:"连接",instrEn:"Join the sentences",body:"下不下雨。我们都出发。"}],note:"“不管”后常用疑问词、正反形式或选择关系。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"不管 is followed by a question word, a yes-no form, or a choice.",typeEn:"Conditional",tier:"HSK4教材内"}]},{num:4,title:"不要太着急赚钱",points:[{id:"4.4.1",name:"动词“以为”",pinyin:"yǐwéi",type:"动词",explainEn:"Use 以为 for what you thought was true, often when it was actually wrong.",structure:"主语 + 以为 + 句子",examples:[{zh:"我以为今天是星期五。",en:"I thought today was Friday."},{zh:"他以为我不来了。",en:"He thought I was not coming."},{zh:"我还以为你在家呢。",en:"I thought you were at home."}],exercises:[{q:"填空：我___你已经走了。",a:"以为",instr:"填空",instrEn:"Fill in the blank",body:"我___你已经走了。"},{q:"翻译：He thought I was not coming.",a:"他以为我不来了。",instr:"翻译",instrEn:"Translate",body:"He thought I was not coming."},{q:"改写：I thought today was Monday.",a:"我以为今天是星期一。",instr:"改写",instrEn:"Rewrite",body:"I thought today was Monday."}],note:"“以为”常暗示后来发现原来的想法不对。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"以为 implies you later found your assumption was wrong.",typeEn:"Verb",tier:"HSK4教材内"},{id:"4.4.2",name:"“原来”和“本来”",pinyin:"yuánlái / běnlái",type:"副词",explainEn:"原来 often shows a newly discovered fact. 本来 shows the original situation or plan.",structure:"原来 + 新发现；本来 + 原计划/原情况",examples:[{zh:"原来你也住在这里。",en:"So you live here too."},{zh:"我本来想坐地铁。",en:"I originally planned to take the subway."},{zh:"原来他就是新经理。",en:"So he is the new manager."}],exercises:[{q:"填空：___你会说中文！",a:"原来",instr:"填空",instrEn:"Fill in the blank",body:"___你会说中文！"},{q:"填空：我___想早点儿回家。",a:"本来",instr:"填空",instrEn:"Fill in the blank",body:"我___想早点儿回家。"},{q:"翻译：So he is the new manager.",a:"原来他就是新经理。",instr:"翻译",instrEn:"Translate",body:"So he is the new manager."}],note:"“原来”常有“现在才知道”的感觉；“本来”强调原先。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'原来 carries "I only just realized"; 本来 stresses the original state.',typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.4.3",name:"副词“并”加强否定",pinyin:"bìng",type:"副词",explainEn:"Use 并 before 不/没 to strongly say “actually not / not at all”.",structure:"并 + 不/没 + 谓语",examples:[{zh:"我并不累。",en:"I am not tired at all."},{zh:"他并没有生气。",en:"He was not actually angry."},{zh:"这件事并不难。",en:"This is not difficult at all."}],exercises:[{q:"填空：我___不觉得贵。",a:"并",instr:"填空",instrEn:"Fill in the blank",body:"我___不觉得贵。"},{q:"翻译：He was not actually angry.",a:"他并没有生气。",instr:"翻译",instrEn:"Translate",body:"He was not actually angry."},{q:"改写：这不难。（用“并”加强）",a:"这件事并不难。",instr:"改写",instrEn:"Rewrite",body:"这不难。（用“并”加强）"}],note:"“并”在这种用法中通常必须和否定词一起出现。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"In this use 并 must appear together with a negative.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.4.4",name:"介词“按照”",pinyin:"ànzhào",type:"介词",explainEn:"Use 按照 to mean “according to / following”.",structure:"按照 + 标准/方法/计划 + V",examples:[{zh:"请按照计划完成工作。",en:"Please finish the work according to the plan."},{zh:"我们按照老师说的做。",en:"We do what the teacher said."},{zh:"按照规定，这里不能停车。",en:"According to the rules, you cannot park here."}],exercises:[{q:"填空：请___计划做。",a:"按照",instr:"填空",instrEn:"Fill in the blank",body:"请___计划做。"},{q:"翻译：According to the rules, you cannot park here.",a:"按照规定，这里不能停车。",instr:"翻译",instrEn:"Translate",body:"According to the rules, you cannot park here."},{q:"排序：按照 / 老师说的 / 做 / 我们",a:"我们按照老师说的做。",instr:"排序",instrEn:"Reorder the words",body:"按照 / 老师说的 / 做 / 我们"}],note:"“按照”后面常接计划、规定、方法、要求等。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"按照 is followed by a plan, rule, method, requirement, etc.",typeEn:"Preposition",tier:"HSK4教材内"},{id:"4.4.5",name:"副词“甚至”",pinyin:"shènzhì",type:"副词",explainEn:"Use 甚至 to add a more surprising or stronger example: “even”.",structure:"普通情况，甚至 + 更强情况",examples:[{zh:"他很忙，甚至没时间吃饭。",en:"He is very busy; he does not even have time to eat."},{zh:"这个孩子会说中文，甚至会写汉字。",en:"This child can speak Chinese and can even write characters."},{zh:"天气很冷，甚至下雪了。",en:"It was very cold; it even snowed."}],exercises:[{q:"填空：他忙得___没时间吃饭。",a:"甚至",instr:"填空",instrEn:"Fill in the blank",body:"他忙得___没时间吃饭。"},{q:"翻译：It even snowed.",a:"甚至下雪了。",instr:"翻译",instrEn:"Translate",body:"It even snowed."},{q:"连接：她会说汉语。她会写汉字。（用“甚至”）",a:"她会说汉语，甚至会写汉字。",instr:"连接",instrEn:"Join the sentences",body:"她会说汉语。她会写汉字。（用“甚至”）"}],note:"“甚至”后面的情况通常比前面更特别、更进一步。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"What follows 甚至 is usually more extreme than what came before.",typeEn:"Adverb",tier:"HSK4教材内"}]},{num:5,title:"只买对的，不买贵的",points:[{id:"4.5.1",name:"副词/动词“肯定”",pinyin:"kěndìng",type:"副词/动词",explainEn:"Use 肯定 to mean “certainly / be sure”.",structure:"肯定 + 谓语；肯定 + 句子",examples:[{zh:"他肯定会来。",en:"He will definitely come."},{zh:"我不能肯定他什么时候到。",en:"I cannot be sure when he will arrive."},{zh:"这次考试你肯定没问题。",en:"You will definitely be fine on this test."}],exercises:[{q:"填空：他___会来。",a:"肯定",instr:"填空",instrEn:"Fill in the blank",body:"他___会来。"},{q:"翻译：I cannot be sure.",a:"我不能肯定。",instr:"翻译",instrEn:"Translate",body:"I cannot be sure."},{q:"选择：表示“definitely”用（肯定 / 偶尔）。",a:"肯定",instr:"选择",instrEn:"Choose",body:"表示“definitely”用（肯定 / 偶尔）。"}],note:"作副词时表示很有把握；作动词时表示“确认/认为确定”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'As an adverb it means "surely"; as a verb, "to confirm/be sure".',typeEn:"Adverb / Verb",tier:"HSK4教材内"},{id:"4.5.2",name:"“再说”表示补充理由或以后再谈",pinyin:"zàishuō",type:"连词/动词",explainEn:"Use 再说 for “besides / moreover” or “talk about it later”.",structure:"理由1，再说 + 理由2；以后再说",examples:[{zh:"今天太晚了，再说我也累了。",en:"It is too late; besides, I am tired."},{zh:"这件事以后再说吧。",en:"Let us talk about this later."},{zh:"我不想买，再说也太贵了。",en:"I do not want to buy it; besides, it is too expensive."}],exercises:[{q:"填空：今天别去了，___外面还下雨。",a:"再说",instr:"填空",instrEn:"Fill in the blank",body:"今天别去了，___外面还下雨。"},{q:"翻译：Let us talk about this later.",a:"这件事以后再说吧。",instr:"翻译",instrEn:"Translate",body:"Let us talk about this later."},{q:"选择：“Besides, it is expensive”中的“besides”可用（再说 / 从来）。",a:"再说",instr:"选择",instrEn:"Choose",body:"“Besides, it is expensive”中的“besides”可用（再说 / 从来）。"}],note:"要根据上下文判断是“补充理由”还是“以后再谈”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'Context decides whether it adds a reason or means "talk about it later".',typeEn:"Conjunction / Verb",tier:"HSK4教材内"},{id:"4.5.3",name:"“实际 / 实际上”",pinyin:"shíjì / shíjìshàng",type:"名词/副词",explainEn:"Use 实际上 to mean “actually / in fact”.",structure:"实际上 + 句子；实际 + 名词",examples:[{zh:"实际上，他并不喜欢这个工作。",en:"Actually, he does not like this job."},{zh:"实际情况跟我们想的不一样。",en:"The real situation is different from what we thought."},{zh:"看起来很简单，实际上很难。",en:"It looks simple, but actually it is difficult."}],exercises:[{q:"填空：看起来容易，___很难。",a:"实际上",instr:"填空",instrEn:"Fill in the blank",body:"看起来容易，___很难。"},{q:"翻译：The real situation is different.",a:"实际情况不一样。",instr:"翻译",instrEn:"Translate",body:"The real situation is different."},{q:"选择：句首“in fact”用（实际上 / 实际问题）。",a:"实际上",instr:"选择",instrEn:"Choose",body:"句首“in fact”用（实际上 / 实际问题）。"}],note:"“实际”常修饰名词；“实际上”常修饰整个句子。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"实际 usually modifies a noun; 实际上 modifies the whole sentence.",typeEn:"Noun / Adverb",tier:"HSK4教材内"},{id:"4.5.4",name:"“对……来说”表示从某人/某方面看",pinyin:"duì ... láishuō",type:"介词结构",explainEn:"Use 对…来说 to mean “for… / from the point of view of…”.",structure:"对 + 人/事物 + 来说，……",examples:[{zh:"对我来说，健康最重要。",en:"For me, health is the most important."},{zh:"对学生来说，这个问题有点儿难。",en:"For students, this question is a little difficult."},{zh:"对他来说，找到工作不容易。",en:"For him, finding a job is not easy."}],exercises:[{q:"填空：___我___，家人最重要。",a:"对；来说",instr:"填空",instrEn:"Fill in the blank",body:"___我___，家人最重要。"},{q:"翻译：For students, this question is difficult.",a:"对学生来说，这个问题很难。",instr:"翻译",instrEn:"Translate",body:"For students, this question is difficult."},{q:"排序：来说 / 对他 / 很简单 / 这件事",a:"对他来说，这件事很简单。",instr:"排序",instrEn:"Reorder the words",body:"来说 / 对他 / 很简单 / 这件事"}],note:"表示评价或判断所站的角度。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Marks the viewpoint from which a judgement is made.",typeEn:"Prep. phrase",tier:"HSK4教材内"},{id:"4.5.5",name:"“尤其”和“特别”",pinyin:"yóuqí / tèbié",type:"副词",explainEn:"Use 尤其 or 特别 to mean “especially”. 尤其 often highlights one item from a group.",structure:"……，尤其 + 突出对象；特别 + Adj/V",examples:[{zh:"我喜欢运动，尤其喜欢游泳。",en:"I like sports, especially swimming."},{zh:"今天特别冷。",en:"It is especially cold today."},{zh:"这里的春天很美，尤其是四月。",en:"Spring is beautiful here, especially April."}],exercises:[{q:"填空：我喜欢水果，___喜欢西瓜。",a:"尤其",instr:"填空",instrEn:"Fill in the blank",body:"我喜欢水果，___喜欢西瓜。"},{q:"翻译：It is especially cold today.",a:"今天特别冷。",instr:"翻译",instrEn:"Translate",body:"It is especially cold today."},{q:"补全：这里很美，___是春天。",a:"尤其",instr:"补全",instrEn:"Complete the sentence",body:"这里很美，___是春天。"}],note:"“尤其”常用于从前面范围中突出一个；“特别”用途更广。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"尤其 singles one out from a set; 特别 is broader in use.",typeEn:"Adverb",tier:"HSK4教材内"}]},{num:6,title:"一分钱一分货",points:[{id:"4.6.1",name:"副词“竟然”表示意外",pinyin:"jìngrán",type:"副词",explainEn:"Use 竟然 when something is very unexpected: “unexpectedly / actually”.",structure:"主语 + 竟然 + 谓语",examples:[{zh:"他竟然忘了我的名字。",en:"He unexpectedly forgot my name."},{zh:"这么难的题，她竟然做对了。",en:"She unexpectedly got such a hard question right."},{zh:"今天这么冷，他竟然穿短袖。",en:"It is so cold, yet he is wearing short sleeves."}],exercises:[{q:"填空：他___没来。",a:"竟然",instr:"填空",instrEn:"Fill in the blank",body:"他___没来。"},{q:"翻译：She unexpectedly got it right.",a:"她竟然做对了。",instr:"翻译",instrEn:"Translate",body:"She unexpectedly got it right."},{q:"选择：表达强烈意外用（竟然 / 按照）。",a:"竟然",instr:"选择",instrEn:"Choose",body:"表达强烈意外用（竟然 / 按照）。"}],note:"“竟然”带明显的惊讶、出乎意料语气。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'竟然 carries clear surprise, "unexpectedly".',typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.6.2",name:"倍数表达“倍”",pinyin:"bèi",type:"数量表达",explainEn:"Use 倍 to say “times as much/many”.",structure:"A 是 B 的 + 数字 + 倍；增加/多 + 数字 + 倍",examples:[{zh:"这个房间是那个房间的两倍大。",en:"This room is twice as big as that room."},{zh:"今年的学生人数是去年的两倍。",en:"The number of students this year is twice last year’s."},{zh:"这台电脑的价格是那台的三倍。",en:"This computer costs three times as much as that one."}],exercises:[{q:"填空：今年人数是去年的两___。",a:"倍",instr:"填空",instrEn:"Fill in the blank",body:"今年人数是去年的两___。"},{q:"翻译：This is twice as big.",a:"这个是那个的两倍大。",instr:"翻译",instrEn:"Translate",body:"This is twice as big."},{q:"写中文：three times the price",a:"价格是三倍。",instr:"写中文",instrEn:"Write in Chinese",body:"three times the price"}],note:"注意英语和汉语对倍数理解有时不同；初学先掌握“A是B的两倍”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'Multiples work differently in English/Chinese; first master "A 是 B 的两倍".',typeEn:"Quantity",tier:"HSK4教材内"},{id:"4.6.3",name:"“值得 / 值”",pinyin:"zhíde / zhí",type:"动词",explainEn:"值得 + verb means “worth doing”. 值 + money means “be worth / cost”.",structure:"值得 + V；值 + 钱/数量",examples:[{zh:"这本书值得看。",en:"This book is worth reading."},{zh:"北京值得去一次。",en:"Beijing is worth visiting once."},{zh:"这个手机值三千块钱。",en:"This phone is worth 3,000 yuan."}],exercises:[{q:"填空：这部电影___看。",a:"值得",instr:"填空",instrEn:"Fill in the blank",body:"这部电影___看。"},{q:"翻译：This book is worth reading.",a:"这本书值得看。",instr:"翻译",instrEn:"Translate",body:"This book is worth reading."},{q:"选择：表示价格“worth 300 yuan”用（值 / 值得）三百元。",a:"值",instr:"选择",instrEn:"Choose",body:"表示价格“worth 300 yuan”用（值 / 值得）三百元。"}],note:"“值得”后接动作；“值”常直接接价格或价值。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"值得 is followed by an action; 值 is followed by a price or value.",typeEn:"Verb",tier:"HSK4教材内"},{id:"4.6.4",name:"代词“其中”",pinyin:"qízhōng",type:"代词",explainEn:"Use 其中 to mean “among them / of these”.",structure:"整体，其中 + 一部分",examples:[{zh:"我们班有二十个人，其中五个是外国学生。",en:"There are 20 students in our class; five of them are foreign students."},{zh:"我买了三本书，其中一本是中文的。",en:"I bought three books; one of them is in Chinese."},{zh:"这里有很多饭店，其中这家最好。",en:"There are many restaurants here; this one is the best among them."}],exercises:[{q:"填空：我买了三本书，___一本是中文的。",a:"其中",instr:"填空",instrEn:"Fill in the blank",body:"我买了三本书，___一本是中文的。"},{q:"翻译：Five of them are foreign students.",a:"其中五个是外国学生。",instr:"翻译",instrEn:"Translate",body:"Five of them are foreign students."},{q:"排序：其中 / 最好 / 这家 / 是",a:"其中这家最好。",instr:"排序",instrEn:"Reorder the words",body:"其中 / 最好 / 这家 / 是"}],note:"前文先有一个整体范围，“其中”再从里面提出一部分。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"First a whole is mentioned; 其中 then singles out a part of it.",typeEn:"Pronoun",tier:"HSK4教材内"},{id:"4.6.5",name:"“（在）……下”表示条件/环境",pinyin:"(zài) ... xià",type:"介词结构",explainEn:"Use 在…下 to mean “under a condition / in an environment”.",structure:"在 + 条件/帮助/影响 + 下",examples:[{zh:"在老师的帮助下，我进步很快。",en:"With the teacher’s help, I improved quickly."},{zh:"在这种情况下，我们只能等。",en:"Under these circumstances, we can only wait."},{zh:"在父母的影响下，他喜欢上了音乐。",en:"Under his parents’ influence, he came to like music."}],exercises:[{q:"填空：___老师的帮助___，我进步很快。",a:"在；下",instr:"填空",instrEn:"Fill in the blank",body:"___老师的帮助___，我进步很快。"},{q:"翻译：Under these circumstances, we can only wait.",a:"在这种情况下，我们只能等。",instr:"翻译",instrEn:"Translate",body:"Under these circumstances, we can only wait."},{q:"选择：“在他的帮助（上 / 下）”表示条件。",a:"下",instr:"选择",instrEn:"Choose",body:"“在他的帮助（上 / 下）”表示条件。"}],note:"这里的“下”不是方位，而表示条件、环境或影响。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Here 下 isn't a location; it marks a condition/environment/influence.",typeEn:"Prep. phrase",tier:"HSK4教材内"}]},{num:7,title:"最好的医生是自己",points:[{id:"4.7.1",name:"“估计”和“可能”",pinyin:"gūjì / kěnéng",type:"动词/副词",explainEn:"估计 means “estimate / guess”. 可能 means “possibly / may”.",structure:"估计 + 句子；可能 + 谓语",examples:[{zh:"我估计他八点到。",en:"I guess he will arrive at eight."},{zh:"明天可能下雨。",en:"It may rain tomorrow."},{zh:"医生估计他很快就会好。",en:"The doctor estimates that he will get better soon."}],exercises:[{q:"填空：我___他九点到。",a:"估计",instr:"填空",instrEn:"Fill in the blank",body:"我___他九点到。"},{q:"填空：明天___下雨。",a:"可能",instr:"填空",instrEn:"Fill in the blank",body:"明天___下雨。"},{q:"翻译：I guess he will come soon.",a:"我估计他很快会来。",instr:"翻译",instrEn:"Translate",body:"I guess he will come soon."}],note:"“估计”强调人的判断；“可能”直接表示可能性。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"估计 stresses a person's estimate; 可能 states possibility directly.",typeEn:"Verb / Adverb",tier:"HSK4教材内"},{id:"4.7.2",name:"“来不及”表示没有足够时间",pinyin:"láibují",type:"可能补语/固定结构",explainEn:"Use 来不及 to mean “not enough time / too late to do something”.",structure:"来不及 + V",examples:[{zh:"快点儿，要来不及了。",en:"Hurry, we are running out of time."},{zh:"我来不及吃早饭。",en:"I do not have time to eat breakfast."},{zh:"现在出发还来得及。",en:"If we leave now, there is still time."}],exercises:[{q:"填空：快点儿，要___了。",a:"来不及",instr:"填空",instrEn:"Fill in the blank",body:"快点儿，要___了。"},{q:"翻译：I do not have time to eat breakfast.",a:"我来不及吃早饭。",instr:"翻译",instrEn:"Translate",body:"I do not have time to eat breakfast."},{q:"选择：还有时间用（来得及 / 来不及）。",a:"来得及",instr:"选择",instrEn:"Choose",body:"还有时间用（来得及 / 来不及）。"}],note:"反义形式是“来得及”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Its opposite is 来得及 (to have enough time).",typeEn:"Potential / Fixed",tier:"HSK4教材内"},{id:"4.7.3",name:"离合词重叠：VVO / AAB",pinyin:"líhécí chóngdié",type:"离合词",explainEn:"Some separable verbs repeat the verb part to mean doing something briefly.",structure:"AB → AAB / VVO",examples:[{zh:"我们散散步吧。",en:"Let us take a short walk."},{zh:"大家鼓鼓掌。",en:"Everyone, give a little applause."},{zh:"我想洗洗澡。",en:"I want to take a quick shower."}],exercises:[{q:"把“散步”变成重叠形式。",a:"散散步"},{q:"翻译：Let us take a short walk.",a:"我们散散步吧。",instr:"翻译",instrEn:"Translate",body:"Let us take a short walk."},{q:"把“鼓掌”变成重叠形式。",a:"鼓鼓掌"}],note:"离合词不能简单按普通双音节动词重叠成ABAB。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Separable verbs don't reduplicate as ABAB like ordinary two-syllable verbs.",typeEn:"Separable verb",tier:"HSK4教材内"},{id:"4.7.4",name:"连词“要是”",pinyin:"yàoshi",type:"连词",explainEn:"Use 要是…就… as a spoken way to say “if… then…”.",structure:"要是 + 条件，就 + 结果",examples:[{zh:"要是明天下雨，我们就不去了。",en:"If it rains tomorrow, we will not go."},{zh:"要是你累了，就休息一下。",en:"If you are tired, take a rest."},{zh:"要是有问题，就给我打电话。",en:"If there is a problem, call me."}],exercises:[{q:"填空：___下雨，我们___不去。",a:"要是；就",instr:"填空",instrEn:"Fill in the blank",body:"___下雨，我们___不去。"},{q:"翻译：If you are tired, take a rest.",a:"要是你累了，就休息一下。",instr:"翻译",instrEn:"Translate",body:"If you are tired, take a rest."},{q:"用“要是……就……”连接：你有时间。我们一起吃饭。",a:"要是你有时间，我们就一起吃饭。"}],note:"“要是”比“如果”更口语。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"要是 is more colloquial than 如果.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.7.5",name:"“既……又/也/还……”",pinyin:"jì ... yòu/yě/hái ...",type:"并列复句",explainEn:"Use 既…又… to say two qualities or actions are both true.",structure:"既 + A，又/也/还 + B",examples:[{zh:"这个地方既安静又漂亮。",en:"This place is both quiet and beautiful."},{zh:"他既会唱歌，也会跳舞。",en:"He can both sing and dance."},{zh:"这份工作既有意思，还能学到东西。",en:"This job is interesting and also lets you learn things."}],exercises:[{q:"填空：这里___安静___漂亮。",a:"既；又",instr:"填空",instrEn:"Fill in the blank",body:"这里___安静___漂亮。"},{q:"翻译：He can both sing and dance.",a:"他既会唱歌，也会跳舞。",instr:"翻译",instrEn:"Translate",body:"He can both sing and dance."},{q:"连接：她认真。她热情。（用“既……又……”）",a:"她既认真又热情。",instr:"连接",instrEn:"Join the sentences",body:"她认真。她热情。（用“既……又……”）"}],note:"强调两个特点或情况同时存在。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Stresses that two features/situations coexist.",typeEn:"Coordinate clause",tier:"HSK4教材内"}]},{num:8,title:"生活中不缺少美",points:[{id:"4.8.1",name:"兼语句“使 + 人/事物 + 谓语”",pinyin:"shǐ",type:"兼语句",explainEn:"Use 使 + person/thing + verb/adjective to mean “make / cause”.",structure:"使 + 人/事物 + V/Adj",examples:[{zh:"运动使我更健康。",en:"Exercise makes me healthier."},{zh:"这件事使他很高兴。",en:"This made him very happy."},{zh:"音乐使我放松。",en:"Music makes me relax."}],exercises:[{q:"填空：运动___身体更健康。",a:"使",instr:"填空",instrEn:"Fill in the blank",body:"运动___身体更健康。"},{q:"翻译：This made him very happy.",a:"这件事使他很高兴。",instr:"翻译",instrEn:"Translate",body:"This made him very happy."},{q:"排序：使 / 音乐 / 放松 / 我",a:"音乐使我放松。",instr:"排序",instrEn:"Reorder the words",body:"使 / 音乐 / 放松 / 我"}],note:"“使”比较书面；口语中常用“让”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"使 is more formal; speech prefers 让.",typeEn:"Pivotal sentence",tier:"HSK4教材内"},{id:"4.8.2",name:"只要……，就……",pinyin:"zhǐyào ... jiù ...",type:"条件复句",explainEn:"Use 只要…就… for “as long as…, then…”.",structure:"只要 + 条件，就 + 结果",examples:[{zh:"只要努力，就会进步。",en:"As long as you work hard, you will improve."},{zh:"只要不下雨，我们就去。",en:"As long as it does not rain, we will go."},{zh:"只要有时间，我就运动。",en:"As long as I have time, I exercise."}],exercises:[{q:"填空：___努力，___会进步。",a:"只要；就",instr:"填空",instrEn:"Fill in the blank",body:"___努力，___会进步。"},{q:"翻译：As long as it does not rain, we will go.",a:"只要不下雨，我们就去。",instr:"翻译",instrEn:"Translate",body:"As long as it does not rain, we will go."},{q:"连接：有时间。我就去看你。",a:"只要有时间，我就去看你。",instr:"连接",instrEn:"Join the sentences",body:"有时间。我就去看你。"}],note:"强调这个条件一满足，后面的结果就可以发生。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Stresses that once the condition holds, the result can occur.",typeEn:"Conditional",tier:"HSK4教材内"},{id:"4.8.3",name:"固定表达“可不是”",pinyin:"kě bú shì",type:"固定表达",explainEn:"Use 可不是 to strongly agree: “Exactly! / You’re right!”.",structure:"A：……？/……。 B：可不是！",examples:[{zh:"A：今天真冷。B：可不是！",en:"A: It is really cold today. B: Exactly!"},{zh:"A：他最近很忙。B：可不是嘛。",en:"A: He has been busy lately. B: Absolutely."},{zh:"A：这里变化真大。B：可不是。",en:"A: This place has changed a lot. B: Exactly."}],exercises:[{q:"填空：A：今天人真多。B：___！",a:"可不是",instr:"填空",instrEn:"Fill in the blank",body:"A：今天人真多。B：___！"},{q:"翻译：Exactly!",a:"可不是！",instr:"翻译",instrEn:"Translate",body:"Exactly!"},{q:"选择：强烈赞同对方可说（可不是 / 否则）。",a:"可不是",instr:"选择",instrEn:"Choose",body:"强烈赞同对方可说（可不是 / 否则）。"}],note:"是口语固定说法，不是普通的“不是”否定句。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"A fixed spoken expression, not an ordinary 不是 negative.",typeEn:"Fixed expression",tier:"HSK4教材内"},{id:"4.8.4",name:"连词“因此”",pinyin:"yīncǐ",type:"连词",explainEn:"Use 因此 to mean “therefore / so”. It is more formal than 所以.",structure:"原因，因此 + 结果",examples:[{zh:"他生病了，因此没有来上课。",en:"He was sick; therefore, he did not come to class."},{zh:"今天下大雨，因此比赛取消了。",en:"It rained heavily; therefore, the game was canceled."},{zh:"时间不够，因此我们明天继续。",en:"There is not enough time; therefore, we will continue tomorrow."}],exercises:[{q:"填空：他生病了，___没来。",a:"因此",instr:"填空",instrEn:"Fill in the blank",body:"他生病了，___没来。"},{q:"翻译：Therefore, we will continue tomorrow.",a:"因此我们明天继续。",instr:"翻译",instrEn:"Translate",body:"Therefore, we will continue tomorrow."},{q:"选择：较书面的“所以”可用（因此 / 可不是）。",a:"因此",instr:"选择",instrEn:"Choose",body:"较书面的“所以”可用（因此 / 可不是）。"}],note:"“因此”常用于书面语或较正式表达。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"因此 is used in writing or more formal speech.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.8.5",name:"“往往、经常、常”表示频率",pinyin:"wǎngwǎng / jīngcháng / cháng",type:"频率副词",explainEn:"往往 means something often happens in a typical situation. 经常/常 simply mean “often”.",structure:"往往/经常/常 + V",examples:[{zh:"周末这里往往人很多。",en:"This place is often crowded on weekends."},{zh:"我经常坐地铁上班。",en:"I often take the subway to work."},{zh:"他常给父母打电话。",en:"He often calls his parents."}],exercises:[{q:"填空：周末这里___人很多。",a:"往往",instr:"填空",instrEn:"Fill in the blank",body:"周末这里___人很多。"},{q:"翻译：I often take the subway to work.",a:"我经常坐地铁上班。",instr:"翻译",instrEn:"Translate",body:"I often take the subway to work."},{q:"选择：表示一般习惯可用（经常 / 因此）。",a:"经常",instr:"选择",instrEn:"Choose",body:"表示一般习惯可用（经常 / 因此）。"}],note:"“往往”常和某种条件、规律一起出现；“经常/常”更普通。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"往往 pairs with a condition/pattern; 经常/常 are more general.",typeEn:"Frequency adverb",tier:"HSK4教材内"}]},{num:9,title:"阳光总在风雨后",points:[{id:"4.9.1",name:"副词“难道”构成反问",pinyin:"nándào",type:"反问句",explainEn:"Use 难道…吗？ to make a strong rhetorical question.",structure:"难道 + 句子 +（吗）？",examples:[{zh:"难道你不知道吗？",en:"Don’t you know?"},{zh:"这么简单，难道你不会做吗？",en:"It is so simple—can’t you do it?"},{zh:"难道他真的不来了？",en:"Could it really be that he is not coming?"}],exercises:[{q:"填空：___你不知道吗？",a:"难道",instr:"填空",instrEn:"Fill in the blank",body:"___你不知道吗？"},{q:"翻译：Can’t you do it?",a:"难道你不会做吗？",instr:"翻译",instrEn:"Translate",body:"Can’t you do it?"},{q:"排序：难道 / 他 / 不 / 知道 / 吗",a:"难道他不知道吗？",instr:"排序",instrEn:"Reorder the words",body:"难道 / 他 / 不 / 知道 / 吗"}],note:"反问通常表达说话人已经有明显判断。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The rhetorical question shows the speaker already has a clear judgement.",typeEn:"Rhetorical question",tier:"HSK4教材内"},{id:"4.9.2",name:"“通过”和“经过”",pinyin:"tōngguò / jīngguò",type:"介词/动词",explainEn:"通过 often means “through a method”. 经过 often means “after going through a process/place”.",structure:"通过 + 方法；经过 + 过程/地点",examples:[{zh:"通过练习，我的汉语进步了。",en:"Through practice, my Chinese improved."},{zh:"经过努力，他终于成功了。",en:"After hard work, he finally succeeded."},{zh:"上班路上要经过一个公园。",en:"I pass a park on my way to work."}],exercises:[{q:"填空：___练习，我进步了。",a:"通过",instr:"填空",instrEn:"Fill in the blank",body:"___练习，我进步了。"},{q:"填空：___努力，他成功了。",a:"经过",instr:"填空",instrEn:"Fill in the blank",body:"___努力，他成功了。"},{q:"翻译：I pass a park on my way to work.",a:"我上班路上经过一个公园。",instr:"翻译",instrEn:"Translate",body:"I pass a park on my way to work."}],note:"“通过”强调手段；“经过”强调过程或经过某地。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"通过 stresses the means; 经过 stresses the process or passing a place.",typeEn:"Preposition / Verb",tier:"HSK4教材内"},{id:"4.9.3",name:"连词“可是”",pinyin:"kěshì",type:"连词",explainEn:"Use 可是 to mean “but / however” in spoken Chinese.",structure:"A，可是 + B",examples:[{zh:"我想去，可是今天没时间。",en:"I want to go, but I have no time today."},{zh:"这个办法很好，可是有点儿贵。",en:"This method is good, but a little expensive."},{zh:"他很年轻，可是很有经验。",en:"He is young, but very experienced."}],exercises:[{q:"填空：我想买，___太贵了。",a:"可是",instr:"填空",instrEn:"Fill in the blank",body:"我想买，___太贵了。"},{q:"翻译：He is young, but very experienced.",a:"他很年轻，可是很有经验。",instr:"翻译",instrEn:"Translate",body:"He is young, but very experienced."},{q:"连接：我很累。我还不能休息。",a:"我很累，可是还不能休息。",instr:"连接",instrEn:"Join the sentences",body:"我很累。我还不能休息。"}],note:"“可是”与“但是”意思接近，口语很常用。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"可是 is close to 但是 and very common in speech.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.9.4",name:"“结果”连接意外结果",pinyin:"jiéguǒ",type:"名词/连词",explainEn:"Use 结果 to introduce the actual result, often an unexpected one.",structure:"前面的情况，结果 + 最终情况",examples:[{zh:"我坐错了车，结果迟到了。",en:"I took the wrong bus, and as a result I was late."},{zh:"他没带伞，结果淋湿了。",en:"He did not bring an umbrella, so he got wet."},{zh:"我找了很久，结果手机就在桌子上。",en:"I looked for a long time; it turned out the phone was on the table."}],exercises:[{q:"填空：我坐错车，___迟到了。",a:"结果",instr:"填空",instrEn:"Fill in the blank",body:"我坐错车，___迟到了。"},{q:"翻译：It turned out the phone was on the table.",a:"结果手机就在桌子上。",instr:"翻译",instrEn:"Translate",body:"It turned out the phone was on the table."},{q:"用“结果”连接：他没带伞。他淋湿了。",a:"他没带伞，结果淋湿了。",instr:"用“结果”连接",instrEn:"Join with 结果",body:"他没带伞。他淋湿了。"}],note:"常表示事情最后出现的实际结果。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Marks the actual result that finally occurred.",typeEn:"Noun / Conjunction",tier:"HSK4教材内"},{id:"4.9.5",name:"“上百、上千、上万”表示很多",pinyin:"shàng bǎi / shàng qiān / shàng wàn",type:"概数表达",explainEn:"Use 上百/上千/上万 to mean “hundreds / thousands / tens of thousands”.",structure:"上 + 百/千/万 + 量词/名词",examples:[{zh:"这里每天有上百个人来参观。",en:"Hundreds of people visit here every day."},{zh:"网上有上千张照片。",en:"There are thousands of photos online."},{zh:"这个城市有上万名学生。",en:"This city has tens of thousands of students."}],exercises:[{q:"填空：这里有___百个人。",a:"上",instr:"填空",instrEn:"Fill in the blank",body:"这里有___百个人。"},{q:"翻译：thousands of photos",a:"上千张照片",instr:"翻译",instrEn:"Translate",body:"thousands of photos"},{q:"选择：“hundreds of people”可说（上百人 / 一百上人）。",a:"上百人",instr:"选择",instrEn:"Choose",body:"“hundreds of people”可说（上百人 / 一百上人）。"}],note:"“上”放在百、千、万前表示大概超过这个数量级。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'上 before 百/千/万 means "up to/over" that order of magnitude.',typeEn:"Approx. number",tier:"HSK4教材内"}]},{num:10,title:"幸福的标准",points:[{id:"4.10.1",name:"“不过”和“但是”",pinyin:"búguò / dànshì",type:"连词",explainEn:"Both mean “but”. 不过 often sounds lighter and can add a small limitation.",structure:"A，不过/但是 + B",examples:[{zh:"这个工作很好，不过有点儿远。",en:"This job is good, but it is a little far."},{zh:"我想去，但是今天没时间。",en:"I want to go, but I have no time today."},{zh:"他说得不错，不过还可以更清楚。",en:"He spoke well, but he could be clearer."}],exercises:[{q:"填空：这个办法不错，___有点儿贵。",a:"不过",instr:"填空",instrEn:"Fill in the blank",body:"这个办法不错，___有点儿贵。"},{q:"翻译：I want to go, but I have no time.",a:"我想去，但是今天没时间。",instr:"翻译",instrEn:"Translate",body:"I want to go, but I have no time."},{q:"选择：语气较轻的“but”常用（不过 / 因此）。",a:"不过",instr:"选择",instrEn:"Choose",body:"语气较轻的“but”常用（不过 / 因此）。"}],note:"“不过”常用于补充一个限制；“但是”是普通转折。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"不过 adds a mild qualification; 但是 is a plain contrast.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.10.2",name:"副词“确实”",pinyin:"quèshí",type:"副词",explainEn:"Use 确实 to mean “really / indeed”, confirming something is true.",structure:"确实 + 谓语",examples:[{zh:"这个问题确实很难。",en:"This question is indeed difficult."},{zh:"他确实进步了很多。",en:"He really has improved a lot."},{zh:"这里的风景确实漂亮。",en:"The scenery here is truly beautiful."}],exercises:[{q:"填空：这个问题___很难。",a:"确实",instr:"填空",instrEn:"Fill in the blank",body:"这个问题___很难。"},{q:"翻译：He really improved a lot.",a:"他确实进步了很多。",instr:"翻译",instrEn:"Translate",body:"He really improved a lot."},{q:"选择：确认事实用（确实 / 甚至）。",a:"确实",instr:"选择",instrEn:"Choose",body:"确认事实用（确实 / 甚至）。"}],note:"强调说话人确认某个事实是真的。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Stresses the speaker confirms a fact is true.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.10.3",name:"“在……看来”表示观点",pinyin:"zài ... kànlái",type:"介词结构",explainEn:"Use 在…看来 to mean “in someone’s view / in the opinion of…”.",structure:"在 + 人 + 看来，……",examples:[{zh:"在我看来，健康最重要。",en:"In my view, health is the most important."},{zh:"在老师看来，他进步很大。",en:"In the teacher’s view, he has improved a lot."},{zh:"在很多人看来，这个办法不错。",en:"In many people’s view, this method is good."}],exercises:[{q:"填空：___我___，这不难。",a:"在；看来",instr:"填空",instrEn:"Fill in the blank",body:"___我___，这不难。"},{q:"翻译：In the teacher’s view, he improved a lot.",a:"在老师看来，他进步很大。",instr:"翻译",instrEn:"Translate",body:"In the teacher’s view, he improved a lot."},{q:"排序：看来 / 在我 / 很重要 / 家庭",a:"在我看来，家庭很重要。",instr:"排序",instrEn:"Reorder the words",body:"看来 / 在我 / 很重要 / 家庭"}],note:"用于明确说明一个观点是从谁的角度出发。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Makes clear whose viewpoint an opinion comes from.",typeEn:"Prep. phrase",tier:"HSK4教材内"},{id:"4.10.4",name:"连词“由于”",pinyin:"yóuyú",type:"连词/介词",explainEn:"Use 由于 to mean “because of / due to”. It is more formal than 因为.",structure:"由于 + 原因，（所以/因此）+ 结果",examples:[{zh:"由于下雨，比赛取消了。",en:"Because of the rain, the game was canceled."},{zh:"由于工作太忙，他没来。",en:"Because work was too busy, he did not come."},{zh:"由于你的帮助，我顺利完成了工作。",en:"Thanks to your help, I completed the work successfully."}],exercises:[{q:"填空：___下雨，比赛取消了。",a:"由于",instr:"填空",instrEn:"Fill in the blank",body:"___下雨，比赛取消了。"},{q:"翻译：Because work was too busy, he did not come.",a:"由于工作太忙，他没来。",instr:"翻译",instrEn:"Translate",body:"Because work was too busy, he did not come."},{q:"连接：你帮助我。我顺利完成了工作。（用“由于”）",a:"由于你的帮助，我顺利完成了工作。",instr:"连接",instrEn:"Join the sentences",body:"你帮助我。我顺利完成了工作。（用“由于”）"}],note:"“由于”更书面，后面常和“因此”搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"由于 is more formal and often pairs with 因此.",typeEn:"Conjunction / Prep.",tier:"HSK4教材内"},{id:"4.10.5",name:"“比如”举例",pinyin:"bǐrú",type:"动词/介词",explainEn:"Use 比如 to give an example: “for example / such as”.",structure:"比如 + 例子",examples:[{zh:"我喜欢很多运动，比如游泳和跑步。",en:"I like many sports, such as swimming and running."},{zh:"北京有很多名胜，比如长城。",en:"Beijing has many famous sights, such as the Great Wall."},{zh:"你可以吃点儿水果，比如苹果。",en:"You can eat some fruit, for example an apple."}],exercises:[{q:"填空：我喜欢水果，___苹果和西瓜。",a:"比如",instr:"填空",instrEn:"Fill in the blank",body:"我喜欢水果，___苹果和西瓜。"},{q:"翻译：For example, the Great Wall.",a:"比如长城。",instr:"翻译",instrEn:"Translate",body:"For example, the Great Wall."},{q:"用“比如”举两个运动的例子。",a:"我喜欢运动，比如游泳和跑步。"}],note:"“比如”后面直接给出具体例子。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"比如 is followed directly by a concrete example.",typeEn:"Verb / Preposition",tier:"HSK4教材内"}]},{num:11,title:"读书好，读好书，好读书",points:[{id:"4.11.1",name:"“连……都/也……”表示强调",pinyin:"lián ... dōu/yě ...",type:"强调结构",explainEn:"Use 连…都/也… to mean “even…”, emphasizing an extreme example.",structure:"连 + 强调对象 + 都/也 + 谓语",examples:[{zh:"这个问题连老师都不知道。",en:"Even the teacher does not know this question."},{zh:"他忙得连饭都没吃。",en:"He was so busy that he did not even eat."},{zh:"这么简单的字，连孩子也会写。",en:"Even a child can write such a simple character."}],exercises:[{q:"填空：这个问题___老师___不知道。",a:"连；都",instr:"填空",instrEn:"Fill in the blank",body:"这个问题___老师___不知道。"},{q:"翻译：He did not even eat.",a:"他连饭都没吃。",instr:"翻译",instrEn:"Translate",body:"He did not even eat."},{q:"连接：这个字很简单。孩子也会写。（用“连……都……”）",a:"这个字连孩子都会写。",instr:"连接",instrEn:"Join the sentences",body:"这个字很简单。孩子也会写。（用“连……都……”）"}],note:"“连”提出最意外或最极端的例子，“都/也”呼应。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"连 raises the most surprising/extreme case, echoed by 都/也.",typeEn:"Emphatic structure",tier:"HSK4教材内"},{id:"4.11.2",name:"连词“否则”",pinyin:"fǒuzé",type:"连词",explainEn:"Use 否则 to mean “otherwise”.",structure:"做A，否则 + 不好的结果",examples:[{zh:"快点儿，否则我们会迟到。",en:"Hurry, otherwise we will be late."},{zh:"你要多穿一点儿，否则会感冒。",en:"Wear more, otherwise you may catch a cold."},{zh:"现在就走，否则赶不上车了。",en:"Leave now, otherwise you will miss the bus."}],exercises:[{q:"填空：快点儿，___会迟到。",a:"否则",instr:"填空",instrEn:"Fill in the blank",body:"快点儿，___会迟到。"},{q:"翻译：Otherwise you will miss the bus.",a:"否则赶不上车了。",instr:"翻译",instrEn:"Translate",body:"Otherwise you will miss the bus."},{q:"用“否则”连接：早点睡。明天会很累。",a:"早点睡，否则明天会很累。",instr:"用“否则”连接",instrEn:"Join with 否则",body:"早点睡。明天会很累。"}],note:"前面通常是应该做的事，后面说明不这样做的结果。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The first part is what should be done; then the result of not doing it.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.11.3",name:"“无论”和“不管”",pinyin:"wúlùn / bùguǎn",type:"条件复句",explainEn:"Both mean “no matter…”. 无论 is a little more formal.",structure:"无论/不管 + 疑问形式，都/也 + 结果",examples:[{zh:"无论多忙，我都要吃早饭。",en:"No matter how busy I am, I eat breakfast."},{zh:"不管你去哪儿，我都支持你。",en:"No matter where you go, I support you."},{zh:"无论结果怎么样，我们都要努力。",en:"No matter what the result is, we must work hard."}],exercises:[{q:"填空：___多难，我都不放弃。",a:"无论/不管",instr:"填空",instrEn:"Fill in the blank",body:"___多难，我都不放弃。"},{q:"翻译：No matter where you go, I support you.",a:"不管你去哪儿，我都支持你。",instr:"翻译",instrEn:"Translate",body:"No matter where you go, I support you."},{q:"选择：较正式的“no matter”常用（无论 / 再说）。",a:"无论",instr:"选择",instrEn:"Choose",body:"较正式的“no matter”常用（无论 / 再说）。"}],note:"两者基本意思相同；“无论”书面感稍强。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The two are basically the same; 无论 feels a bit more formal.",typeEn:"Conditional",tier:"HSK4教材内"},{id:"4.11.4",name:"连词“然而”",pinyin:"rán'ér",type:"连词",explainEn:"Use 然而 to mean “however / yet”. It is formal and often used in writing.",structure:"A，然而 + B",examples:[{zh:"他很努力，然而结果并不好。",en:"He worked hard; however, the result was not good."},{zh:"这本书很短，然而很有意思。",en:"This book is short, yet very interesting."},{zh:"外面很冷，然而他还是出去了。",en:"It was cold outside; however, he still went out."}],exercises:[{q:"填空：他很努力，___没有成功。",a:"然而",instr:"填空",instrEn:"Fill in the blank",body:"他很努力，___没有成功。"},{q:"翻译：This book is short, yet interesting.",a:"这本书很短，然而很有意思。",instr:"翻译",instrEn:"Translate",body:"This book is short, yet interesting."},{q:"选择：书面语“however”用（然而 / 可不是）。",a:"然而",instr:"选择",instrEn:"Choose",body:"书面语“however”用（然而 / 可不是）。"}],note:"比“但是、可是”更书面。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"More formal than 但是/可是.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.11.5",name:"副词/连词“同时”",pinyin:"tóngshí",type:"副词/连词",explainEn:"Use 同时 to mean “at the same time / meanwhile”.",structure:"A，同时 + B",examples:[{zh:"学习语言要多听，同时也要多说。",en:"To learn a language, listen more and also speak more."},{zh:"他工作，同时也在学习。",en:"He works and studies at the same time."},{zh:"这个办法省时间，同时也省钱。",en:"This method saves time and money at the same time."}],exercises:[{q:"填空：要多听，___也要多说。",a:"同时",instr:"填空",instrEn:"Fill in the blank",body:"要多听，___也要多说。"},{q:"翻译：This saves time and money at the same time.",a:"这个办法省时间，同时也省钱。",instr:"翻译",instrEn:"Translate",body:"This saves time and money at the same time."},{q:"用“同时”连接：他工作。他学习。",a:"他工作，同时也学习。",instr:"用“同时”连接",instrEn:"Join with 同时",body:"他工作。他学习。"}],note:"既可以表示两件事同一时间发生，也可以连接并列信息。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Can mean two things happen at once, or link parallel information.",typeEn:"Adverb / Conjunction",tier:"HSK4教材内"}]},{num:12,title:"用心发现世界",points:[{id:"4.12.1",name:"连词“并且”",pinyin:"bìngqiě",type:"连词",explainEn:"Use 并且 to add another related action or fact: “and / furthermore”.",structure:"A，并且 + B",examples:[{zh:"他认真工作，并且每天学习。",en:"He works hard and also studies every day."},{zh:"这个办法简单，并且很有效。",en:"This method is simple and effective."},{zh:"她会说汉语，并且说得很好。",en:"She can speak Chinese, and speaks it very well."}],exercises:[{q:"填空：这个办法简单，___有效。",a:"并且",instr:"填空",instrEn:"Fill in the blank",body:"这个办法简单，___有效。"},{q:"翻译：She can speak Chinese and speaks it well.",a:"她会说汉语，并且说得很好。",instr:"翻译",instrEn:"Translate",body:"She can speak Chinese and speaks it well."},{q:"连接：他很认真。他很有经验。",a:"他很认真，并且很有经验。",instr:"连接",instrEn:"Join the sentences",body:"他很认真。他很有经验。"}],note:"“并且”比“而且”更适合连接两个并列动作或情况。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"并且 suits linking two parallel actions/situations better than 而且.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.12.2",name:"再……也……表示“无论多么……”",pinyin:"zài ... yě ...",type:"让步结构",explainEn:"Use 再 + adjective/verb + 也… to mean “no matter how… still…”.",structure:"再 + Adj/V，也 + 结果",examples:[{zh:"再忙也要吃饭。",en:"No matter how busy you are, you still need to eat."},{zh:"再难我也要试试。",en:"No matter how difficult it is, I will try."},{zh:"天气再冷，他也坚持跑步。",en:"No matter how cold it is, he keeps running."}],exercises:[{q:"填空：___忙___要休息。",a:"再；也",instr:"填空",instrEn:"Fill in the blank",body:"___忙___要休息。"},{q:"翻译：No matter how difficult it is, I will try.",a:"再难我也要试试。",instr:"翻译",instrEn:"Translate",body:"No matter how difficult it is, I will try."},{q:"连接：天气很冷。他还是跑步。（用“再……也……”）",a:"天气再冷，他也跑步。",instr:"连接",instrEn:"Join the sentences",body:"天气很冷。他还是跑步。（用“再……也……”）"}],note:"配套课程标注为HSK5扩展；教材中出现，可作为理解项。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Marked as an HSK5 extension; appears in the text as a comprehension item.",typeEn:"Concessive structure",tier:"教材高阶扩展（配套课程标注HSK5）"},{id:"4.12.3",name:"“对于”和“关于”",pinyin:"duìyú / guānyú",type:"介词",explainEn:"对于 means “regarding / toward” a target of attitude. 关于 means “about” a topic.",structure:"对于 + 对象 + 评价；关于 + 话题 + 内容",examples:[{zh:"对于这个问题，我有不同的看法。",en:"Regarding this question, I have a different view."},{zh:"关于明天的会议，我想说两句。",en:"About tomorrow’s meeting, I want to say a few words."},{zh:"他对于中国文化很感兴趣。",en:"He is very interested in Chinese culture."}],exercises:[{q:"填空：___这个问题，我有一个看法。",a:"对于",instr:"填空",instrEn:"Fill in the blank",body:"___这个问题，我有一个看法。"},{q:"填空：这是一本___中国历史的书。",a:"关于",instr:"填空",instrEn:"Fill in the blank",body:"这是一本___中国历史的书。"},{q:"选择：表示话题“about Chinese culture”常用（关于 / 对于）。",a:"关于",instr:"选择",instrEn:"Choose",body:"表示话题“about Chinese culture”常用（关于 / 对于）。"}],note:"配套课程标注为HSK5扩展；“对于”偏对象，“关于”偏话题。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"HSK5 extension: 对于 targets an object, 关于 a topic.",typeEn:"Preposition",tier:"教材高阶扩展（配套课程标注HSK5）"},{id:"4.12.4",name:"名量词重叠：“个个、件件……”",pinyin:"míng liàngcí chóngdié",type:"重叠结构",explainEn:"Repeat a measure word to mean “every one / each”.",structure:"量词 + 量词 + 都……",examples:[{zh:"这些苹果个个都很甜。",en:"Every one of these apples is sweet."},{zh:"这些衣服件件都很漂亮。",en:"Every piece of clothing is beautiful."},{zh:"大家个个都很高兴。",en:"Everyone is happy."}],exercises:[{q:"填空：这些苹果___都很甜。",a:"个个",instr:"填空",instrEn:"Fill in the blank",body:"这些苹果___都很甜。"},{q:"翻译：Every piece is beautiful.",a:"件件都很漂亮。",instr:"翻译",instrEn:"Translate",body:"Every piece is beautiful."},{q:"把“件”重叠。",a:"件件"}],note:"通常和“都”一起使用。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Usually used together with 都.",typeEn:"Reduplication",tier:"HSK4教材内"},{id:"4.12.5",name:"“相反”表示相反情况",pinyin:"xiāngfǎn",type:"形容词/副词",explainEn:"Use 相反 to mean “opposite / on the contrary”.",structure:"A；相反，B",examples:[{zh:"我不觉得累，相反，我觉得很轻松。",en:"I do not feel tired; on the contrary, I feel relaxed."},{zh:"他没有生气，相反，他笑了。",en:"He was not angry; on the contrary, he smiled."},{zh:"这两个办法完全相反。",en:"These two methods are completely opposite."}],exercises:[{q:"填空：他没生气，___还笑了。",a:"相反",instr:"填空",instrEn:"Fill in the blank",body:"他没生气，___还笑了。"},{q:"翻译：These two methods are opposite.",a:"这两个办法相反。",instr:"翻译",instrEn:"Translate",body:"These two methods are opposite."},{q:"选择：“on the contrary”用（相反 / 其中）。",a:"相反",instr:"选择",instrEn:"Choose",body:"“on the contrary”用（相反 / 其中）。"}],note:"可作形容词，也可放在后一个分句前表示相反结果。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Can be an adjective, or open the second clause to show an opposite result.",typeEn:"Adjective / Adverb",tier:"HSK4教材内"}]},{num:13,title:"喝着茶看京剧",points:[{id:"4.13.1",name:"“大概”和“也许”",pinyin:"dàgài / yěxǔ",type:"副词",explainEn:"Both show uncertainty. 大概 often means “probably/about”; 也许 means “maybe”.",structure:"大概/也许 + 句子",examples:[{zh:"他大概九点到。",en:"He will probably arrive at nine."},{zh:"也许明天会下雨。",en:"Maybe it will rain tomorrow."},{zh:"这件衣服大概三百块钱。",en:"This clothing costs about 300 yuan."}],exercises:[{q:"填空：他___九点到。",a:"大概",instr:"填空",instrEn:"Fill in the blank",body:"他___九点到。"},{q:"翻译：Maybe it will rain tomorrow.",a:"也许明天会下雨。",instr:"翻译",instrEn:"Translate",body:"Maybe it will rain tomorrow."},{q:"选择：表示大约数量也可用（大概 / 也许）三百元。",a:"大概",instr:"选择",instrEn:"Choose",body:"表示大约数量也可用（大概 / 也许）三百元。"}],note:"“大概”还能表示约数；“也许”主要表示可能性。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"大概 can also give an approximate number; 也许 mainly shows possibility.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.13.2",name:"副词“偶尔”",pinyin:"ǒu'ěr",type:"副词",explainEn:"Use 偶尔 to mean “occasionally / once in a while”.",structure:"偶尔 + V",examples:[{zh:"我偶尔喝咖啡。",en:"I drink coffee occasionally."},{zh:"他偶尔坐地铁上班。",en:"He occasionally takes the subway to work."},{zh:"周末我偶尔去爬山。",en:"I sometimes go hiking on weekends."}],exercises:[{q:"填空：我___喝一次咖啡。",a:"偶尔",instr:"填空",instrEn:"Fill in the blank",body:"我___喝一次咖啡。"},{q:"翻译：He occasionally takes the subway.",a:"他偶尔坐地铁。",instr:"翻译",instrEn:"Translate",body:"He occasionally takes the subway."},{q:"选择：频率很低用（偶尔 / 经常）。",a:"偶尔",instr:"选择",instrEn:"Choose",body:"频率很低用（偶尔 / 经常）。"}],note:"频率低于“有时、经常”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Lower in frequency than 有时/经常.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.13.3",name:"介词“由”",pinyin:"yóu",type:"介词",explainEn:"Use 由 to mean “from / by”, often for starting point or responsibility.",structure:"由 + 地点/人 + V",examples:[{zh:"这次活动由我负责。",en:"I am responsible for this activity."},{zh:"飞机由北京飞往上海。",en:"The plane flies from Beijing to Shanghai."},{zh:"这个问题由老师来解释。",en:"The teacher will explain this question."}],exercises:[{q:"填空：这次活动___我负责。",a:"由",instr:"填空",instrEn:"Fill in the blank",body:"这次活动___我负责。"},{q:"翻译：The teacher will explain this question.",a:"这个问题由老师来解释。",instr:"翻译",instrEn:"Translate",body:"The teacher will explain this question."},{q:"排序：由 / 北京 / 飞机 / 上海 / 飞往",a:"飞机由北京飞往上海。",instr:"排序",instrEn:"Reorder the words",body:"由 / 北京 / 飞机 / 上海 / 飞往"}],note:"“由”比较书面，可表示起点，也可引出负责人。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"由 is formal; it can mark a starting point or introduce who's responsible.",typeEn:"Preposition",tier:"HSK4教材内"},{id:"4.13.4",name:"动词“进行”",pinyin:"jìnxíng",type:"动词",explainEn:"Use 进行 before a formal two-syllable action: “carry out / conduct”.",structure:"进行 + 双音节动作名词",examples:[{zh:"我们正在进行讨论。",en:"We are having a discussion."},{zh:"学校要进行考试。",en:"The school will hold an exam."},{zh:"他们对这个问题进行了研究。",en:"They carried out research on this question."}],exercises:[{q:"填空：我们正在___讨论。",a:"进行",instr:"填空",instrEn:"Fill in the blank",body:"我们正在___讨论。"},{q:"翻译：They carried out research.",a:"他们进行了研究。",instr:"翻译",instrEn:"Translate",body:"They carried out research."},{q:"选择：正式表达“conduct a discussion”可说（进行讨论 / 做讨论）。",a:"进行讨论",instr:"选择",instrEn:"Choose",body:"正式表达“conduct a discussion”可说（进行讨论 / 做讨论）。"}],note:"常和“讨论、调查、研究、比赛、考试”等搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Often pairs with 讨论/调查/研究/比赛/考试.",typeEn:"Verb",tier:"HSK4教材内"},{id:"4.13.5",name:"介词“随着”",pinyin:"suízhe",type:"介词",explainEn:"Use 随着 to mean “as / along with” a change or development.",structure:"随着 + 变化，另一变化",examples:[{zh:"随着天气变冷，穿外套的人越来越多。",en:"As the weather gets colder, more people wear coats."},{zh:"随着时间的变化，他成熟了很多。",en:"As time passed, he became much more mature."},{zh:"随着汉语水平提高，我越来越有信心。",en:"As my Chinese improves, I become more confident."}],exercises:[{q:"填空：___天气变冷，大家穿得更多了。",a:"随着",instr:"填空",instrEn:"Fill in the blank",body:"___天气变冷，大家穿得更多了。"},{q:"翻译：As my Chinese improves, I become more confident.",a:"随着汉语水平提高，我越来越有信心。",instr:"翻译",instrEn:"Translate",body:"As my Chinese improves, I become more confident."},{q:"用“随着”连接：时间过去了。他改变了很多。",a:"随着时间过去，他改变了很多。",instr:"用“随着”连接",instrEn:"Join with 随着",body:"时间过去了。他改变了很多。"}],note:"前后通常是一起发展或变化的情况。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The two parts usually develop or change together.",typeEn:"Preposition",tier:"HSK4教材内"}]},{num:14,title:"保护地球母亲",points:[{id:"4.14.1",name:"“够”表示达到需要的程度",pinyin:"gòu",type:"动词/形容词",explainEn:"Use 够 to mean “enough”.",structure:"够 + Adj/V；数量 + 够不够",examples:[{zh:"这些钱够了。",en:"This money is enough."},{zh:"时间不够，我们明天继续。",en:"There is not enough time; we will continue tomorrow."},{zh:"这个房间够大。",en:"This room is big enough."}],exercises:[{q:"填空：时间不___。",a:"够",instr:"填空",instrEn:"Fill in the blank",body:"时间不___。"},{q:"翻译：This room is big enough.",a:"这个房间够大。",instr:"翻译",instrEn:"Translate",body:"This room is big enough."},{q:"选择：问“Is the money enough?”可说“钱（够不够 / 很够）？”",a:"够不够",instr:"选择",instrEn:"Choose",body:"问“Is the money enough?”可说“钱（够不够 / 很够）？”"}],note:"“够 + 形容词”表示程度达到要求。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"够 + adjective means the degree meets the requirement.",typeEn:"Verb / Adjective",tier:"HSK4教材内"},{id:"4.14.2",name:"介词/方位结构“以”",pinyin:"yǐ",type:"介词/方位词",explainEn:"Use 以 with directions or limits, such as 以上/以下/以东/以西.",structure:"数字/地点 + 以上/以下/以东/以西",examples:[{zh:"十八岁以上的人可以买票。",en:"People aged 18 and above can buy tickets."},{zh:"三十度以下比较舒服。",en:"Below 30 degrees is more comfortable."},{zh:"学校以东有一个公园。",en:"There is a park east of the school."}],exercises:[{q:"填空：十八岁___的人。",a:"以上",instr:"填空",instrEn:"Fill in the blank",body:"十八岁___的人。"},{q:"翻译：There is a park east of the school.",a:"学校以东有一个公园。",instr:"翻译",instrEn:"Translate",body:"There is a park east of the school."},{q:"选择：“below 30 degrees”用“三十度（以下 / 以上）”。",a:"以下",instr:"选择",instrEn:"Choose",body:"“below 30 degrees”用“三十度（以下 / 以上）”。"}],note:"“以”常和上、下、东、西等组成固定方位/范围表达。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"以 combines with 上/下/东/西 into fixed position/range expressions.",typeEn:"Prep. / Locative",tier:"HSK4教材内"},{id:"4.14.3",name:"既然……，就……",pinyin:"jìrán ... jiù ...",type:"因果复句",explainEn:"Use 既然…就… for “since / now that…, then…”.",structure:"既然 + 已知事实，就 + 建议/结论",examples:[{zh:"既然你累了，就休息一下吧。",en:"Since you are tired, take a rest."},{zh:"既然决定了，就认真做。",en:"Since you decided, do it seriously."},{zh:"既然大家都来了，我们就开始吧。",en:"Since everyone is here, let us begin."}],exercises:[{q:"填空：___你累了，___休息吧。",a:"既然；就",instr:"填空",instrEn:"Fill in the blank",body:"___你累了，___休息吧。"},{q:"翻译：Since everyone is here, let us begin.",a:"既然大家都来了，我们就开始吧。",instr:"翻译",instrEn:"Translate",body:"Since everyone is here, let us begin."},{q:"连接：你决定了。认真做吧。",a:"既然你决定了，就认真做吧。",instr:"连接",instrEn:"Join the sentences",body:"你决定了。认真做吧。"}],note:"“既然”提出已经确定的事实，“就”给出自然结论。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"既然 states an established fact; 就 gives the natural conclusion.",typeEn:"Cause–effect clause",tier:"HSK4教材内"},{id:"4.14.4",name:"“于是”和“因此”",pinyin:"yúshì / yīncǐ",type:"连词",explainEn:"于是 shows the next event caused by the first. 因此 gives a logical result and is more formal.",structure:"情况，于是 + 后续动作；原因，因此 + 结果",examples:[{zh:"他忘了带伞，于是回家去拿。",en:"He forgot his umbrella, so he went home to get it."},{zh:"天气不好，因此比赛取消了。",en:"The weather was bad; therefore, the game was canceled."},{zh:"我听到门响，于是去开门。",en:"I heard the door, so I went to open it."}],exercises:[{q:"填空：他忘了东西，___回去拿。",a:"于是",instr:"填空",instrEn:"Fill in the blank",body:"他忘了东西，___回去拿。"},{q:"填空：天气不好，___比赛取消。",a:"因此",instr:"填空",instrEn:"Fill in the blank",body:"天气不好，___比赛取消。"},{q:"翻译：I heard the door, so I opened it.",a:"我听到门响，于是去开门。",instr:"翻译",instrEn:"Translate",body:"I heard the door, so I opened it."}],note:"“于是”常讲故事中的顺序结果；“因此”更偏逻辑因果。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"于是 tells a sequential result in a story; 因此 is more logical cause-effect.",typeEn:"Conjunction",tier:"HSK4教材内"},{id:"4.14.5",name:"“什么的”表示列举未完",pinyin:"shénme de",type:"列举结构",explainEn:"Use 什么的 after examples to mean “and so on / things like that”.",structure:"A、B什么的",examples:[{zh:"我喜欢苹果、香蕉什么的。",en:"I like apples, bananas, and things like that."},{zh:"周末可以看电影、逛街什么的。",en:"On weekends you can watch movies, shop, and so on."},{zh:"他会做饭、开车什么的。",en:"He can cook, drive, and things like that."}],exercises:[{q:"填空：我喜欢苹果、香蕉___。",a:"什么的",instr:"填空",instrEn:"Fill in the blank",body:"我喜欢苹果、香蕉___。"},{q:"翻译：watch movies, shop, and so on",a:"看电影、逛街什么的",instr:"翻译",instrEn:"Translate",body:"watch movies, shop, and so on"},{q:"用“什么的”列举两个周末活动。",a:"周末我会看电影、运动什么的。"}],note:"口语常用，表示还有别的类似内容没有全部说出来。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Colloquial; means there are more similar things left unsaid.",typeEn:"Enumeration",tier:"HSK4教材内"}]},{num:15,title:"教育孩子的艺术",points:[{id:"4.15.1",name:"“想起来”表示回忆起来",pinyin:"xiǎngqǐlái",type:"趋向补语引申",explainEn:"Use 想起来 to mean “remember / recall”.",structure:"想起来 + 人/事；想起 + 宾语 + 来",examples:[{zh:"我突然想起来他的名字了。",en:"I suddenly remembered his name."},{zh:"你想起来了吗？",en:"Did you remember?"},{zh:"我想起一件事来。",en:"I remembered something."}],exercises:[{q:"填空：我终于想___他的名字了。",a:"起来",instr:"填空",instrEn:"Fill in the blank",body:"我终于想___他的名字了。"},{q:"翻译：Did you remember?",a:"你想起来了吗？",instr:"翻译",instrEn:"Translate",body:"Did you remember?"},{q:"排序：一件事 / 我 / 想起 / 来",a:"我想起一件事来。",instr:"排序",instrEn:"Reorder the words",body:"一件事 / 我 / 想起 / 来"}],note:"“起来”在这里不是实际方向，而表示记忆从无到有。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Here 起来 isn't a real direction; it marks recall coming to mind.",typeEn:"Directional (fig.)",tier:"HSK4教材内"},{id:"4.15.2",name:"动词“弄”",pinyin:"nòng",type:"动词",explainEn:"弄 is a general spoken verb meaning “do / make / get / handle”, depending on context.",structure:"弄 + Adj/结果；把 + O + 弄 + 结果",examples:[{zh:"别把衣服弄脏了。",en:"Do not get the clothes dirty."},{zh:"我把手机弄丢了。",en:"I lost my phone."},{zh:"这个问题我还没弄明白。",en:"I still have not figured this question out."}],exercises:[{q:"填空：别把桌子___脏了。",a:"弄",instr:"填空",instrEn:"Fill in the blank",body:"别把桌子___脏了。"},{q:"翻译：I lost my phone.",a:"我把手机弄丢了。",instr:"翻译",instrEn:"Translate",body:"I lost my phone."},{q:"补全：这个问题我没弄___。",a:"明白",instr:"补全",instrEn:"Complete the sentence",body:"这个问题我没弄___。"}],note:"口语里用途很广，常和结果补语一起使用。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Very versatile in speech, often used with a result complement.",typeEn:"Verb",tier:"HSK4教材内"},{id:"4.15.3",name:"“千万”和“一定”",pinyin:"qiānwàn / yídìng",type:"副词",explainEn:"一定 means “definitely / must”. 千万 strongly warns or reminds: “be sure to / never”.",structure:"一定 + V；千万 + 要/别/不要 + V",examples:[{zh:"你一定要按时来。",en:"You must come on time."},{zh:"路上千万小心。",en:"Be very careful on the way."},{zh:"你千万别忘了带护照。",en:"Be sure not to forget your passport."}],exercises:[{q:"填空：你___要记得。",a:"一定",instr:"填空",instrEn:"Fill in the blank",body:"你___要记得。"},{q:"填空：___别迟到。",a:"千万",instr:"填空",instrEn:"Fill in the blank",body:"___别迟到。"},{q:"翻译：You must come on time.",a:"你一定要按时来。",instr:"翻译",instrEn:"Translate",body:"You must come on time."}],note:"“千万”语气更强，常用于提醒、警告；“一定”更普通。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"千万 is stronger, for reminders/warnings; 一定 is more neutral.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.15.4",name:"“来”表示估计数量/承担动作",pinyin:"lái",type:"动词/助词化用法",explainEn:"来 can be used to take responsibility for an action: “let me/us do it”, or in some approximate expressions.",structure:"我来 + V；由/让 + 人 + 来 + V",examples:[{zh:"这个问题我来回答。",en:"Let me answer this question."},{zh:"饭我来做，你休息吧。",en:"I will make the food; you rest."},{zh:"这件事让他来处理。",en:"Let him handle this matter."}],exercises:[{q:"填空：这个问题我___回答。",a:"来",instr:"填空",instrEn:"Fill in the blank",body:"这个问题我___回答。"},{q:"翻译：Let him handle this matter.",a:"这件事让他来处理。",instr:"翻译",instrEn:"Translate",body:"Let him handle this matter."},{q:"排序：我 / 来 / 饭 / 做",a:"饭我来做。",instr:"排序",instrEn:"Reorder the words",body:"我 / 来 / 饭 / 做"}],note:"本课重点是“来”表示由谁做某件事。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Focus: 来 indicating who will take on an action.",typeEn:"Verb / Particle-like",tier:"HSK4教材内"},{id:"4.15.5",name:"“左右”表示大约",pinyin:"zuǒyòu",type:"概数表达",explainEn:"Use 左右 after a number to mean “about / around”.",structure:"数量 + 左右",examples:[{zh:"我八点左右到。",en:"I will arrive around eight."},{zh:"这里有三十个人左右。",en:"There are about thirty people here."},{zh:"他四十岁左右。",en:"He is around forty years old."}],exercises:[{q:"填空：我八点___到。",a:"左右",instr:"填空",instrEn:"Fill in the blank",body:"我八点___到。"},{q:"翻译：about thirty people",a:"三十个人左右",instr:"翻译",instrEn:"Translate",body:"about thirty people"},{q:"排序：左右 / 四十岁 / 他",a:"他四十岁左右。",instr:"排序",instrEn:"Reorder the words",body:"左右 / 四十岁 / 他"}],note:"放在数量表达后面。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Placed after the quantity.",typeEn:"Approx. number",tier:"HSK4教材内"}]},{num:16,title:"生活可以更美好",points:[{id:"4.16.1",name:"副词“可”加强语气",pinyin:"kě",type:"副词",explainEn:"Use 可 to strongly emphasize a statement: “really / indeed / you know”.",structure:"主语 + 可 + 谓语",examples:[{zh:"你可别忘了。",en:"You really must not forget."},{zh:"这个问题可不简单。",en:"This question is really not simple."},{zh:"他可会做饭了。",en:"He is really good at cooking."}],exercises:[{q:"填空：你___别迟到。",a:"可",instr:"填空",instrEn:"Fill in the blank",body:"你___别迟到。"},{q:"翻译：This is really not simple.",a:"这个问题可不简单。",instr:"翻译",instrEn:"Translate",body:"This is really not simple."},{q:"选择：加强口语语气可用（可 / 由）。",a:"可",instr:"选择",instrEn:"Choose",body:"加强口语语气可用（可 / 由）。"}],note:"这里“可”不是“可以”，而是加强说话人的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Here 可 isn't 可以; it strengthens the speaker's tone.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.16.2",name:"“恐怕”和“怕”",pinyin:"kǒngpà / pà",type:"副词/动词",explainEn:"恐怕 means “I’m afraid / probably”. 怕 can mean “be afraid” or “worry that”.",structure:"恐怕 + 句子；怕 + 名词/句子",examples:[{zh:"恐怕今天来不及了。",en:"I am afraid there is not enough time today."},{zh:"我怕坐飞机。",en:"I am afraid of flying."},{zh:"他怕明天会下雨。",en:"He worries that it may rain tomorrow."}],exercises:[{q:"填空：___今天不行。",a:"恐怕",instr:"填空",instrEn:"Fill in the blank",body:"___今天不行。"},{q:"翻译：I am afraid of flying.",a:"我怕坐飞机。",instr:"翻译",instrEn:"Translate",body:"I am afraid of flying."},{q:"选择：“I’m afraid it won’t work”用（恐怕 / 偶尔）。",a:"恐怕",instr:"选择",instrEn:"Choose",body:"“I’m afraid it won’t work”用（恐怕 / 偶尔）。"}],note:"“恐怕”常是委婉地表达担心或不好的判断。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"恐怕 politely expresses worry or a bad guess.",typeEn:"Adverb / Verb",tier:"HSK4教材内"},{id:"4.16.3",name:"副词“到底”",pinyin:"dàodǐ",type:"副词",explainEn:"Use 到底 in questions to strongly ask “exactly / after all”.",structure:"疑问词/问句 + 到底；到底 + 疑问句",examples:[{zh:"你到底想说什么？",en:"What exactly do you want to say?"},{zh:"他到底去哪儿了？",en:"Where on earth did he go?"},{zh:"这到底是怎么回事？",en:"What exactly is going on?"}],exercises:[{q:"填空：你___想去哪儿？",a:"到底",instr:"填空",instrEn:"Fill in the blank",body:"你___想去哪儿？"},{q:"翻译：What exactly is going on?",a:"这到底是怎么回事？",instr:"翻译",instrEn:"Translate",body:"What exactly is going on?"},{q:"排序：到底 / 他 / 去哪儿 / 了",a:"他到底去哪儿了？",instr:"排序",instrEn:"Reorder the words",body:"到底 / 他 / 去哪儿 / 了"}],note:"常带着急、好奇或追问的语气。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Carries an impatient, curious or pressing tone.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.16.4",name:"“拿……来说”表示举例",pinyin:"ná ... láishuō",type:"举例结构",explainEn:"Use 拿…来说 to mean “take… for example”.",structure:"拿 + 例子 + 来说，……",examples:[{zh:"拿我来说，我每天都运动。",en:"Take me for example: I exercise every day."},{zh:"拿北京来说，春天比较短。",en:"Take Beijing for example: spring is relatively short."},{zh:"拿学习汉语来说，多练习很重要。",en:"Take Chinese study for example: practice is important."}],exercises:[{q:"填空：___我___，我喜欢早起。",a:"拿；来说",instr:"填空",instrEn:"Fill in the blank",body:"___我___，我喜欢早起。"},{q:"翻译：Take Beijing for example.",a:"拿北京来说。",instr:"翻译",instrEn:"Translate",body:"Take Beijing for example."},{q:"用“拿……来说”举“学习汉语”的例子。",a:"拿学习汉语来说，多练习很重要。"}],note:"用于从一个具体例子开始说明观点。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Used to make a point starting from a concrete example.",typeEn:"Example structure",tier:"HSK4教材内"},{id:"4.16.5",name:"能愿动词“敢”",pinyin:"gǎn",type:"能愿动词",explainEn:"Use 敢 + verb to mean “dare to / have the courage to”.",structure:"敢 + V；不敢 + V",examples:[{zh:"我不敢一个人去。",en:"I do not dare to go alone."},{zh:"你敢试试吗？",en:"Do you dare to try?"},{zh:"他敢在大家面前说中文。",en:"He dares to speak Chinese in front of everyone."}],exercises:[{q:"填空：我不___一个人去。",a:"敢",instr:"填空",instrEn:"Fill in the blank",body:"我不___一个人去。"},{q:"翻译：Do you dare to try?",a:"你敢试试吗？",instr:"翻译",instrEn:"Translate",body:"Do you dare to try?"},{q:"改成否定：他敢说。",a:"他不敢说。",instr:"改成否定",instrEn:"Make it negative",body:"他敢说。"}],note:"表示有没有勇气做某事。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Shows whether one dares to do something.",typeEn:"Modal verb",tier:"HSK4教材内"}]},{num:17,title:"人与自然",points:[{id:"4.17.1",name:"副词“倒”表示与预期不同/让步",pinyin:"dào",type:"副词",explainEn:"Use 倒 to show a mild contrast or an unexpected view: “actually / on the other hand”.",structure:"主语 + 倒 + 谓语",examples:[{zh:"这个办法倒不错。",en:"This method is actually pretty good."},{zh:"他虽然年轻，经验倒不少。",en:"Although he is young, he actually has quite a lot of experience."},{zh:"我不累，倒是有点儿饿。",en:"I am not tired; actually, I am a little hungry."}],exercises:[{q:"填空：这个办法___不错。",a:"倒",instr:"填空",instrEn:"Fill in the blank",body:"这个办法___不错。"},{q:"翻译：I’m not tired; actually, I’m hungry.",a:"我不累，倒是有点儿饿。",instr:"翻译",instrEn:"Translate",body:"I’m not tired; actually, I’m hungry."},{q:"选择：表示轻微转折可用（倒 / 因此）。",a:"倒",instr:"选择",instrEn:"Choose",body:"表示轻微转折可用（倒 / 因此）。"}],note:"“倒”常有“跟想象不一样”或温和转折的感觉。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:'倒 often feels "contrary to expectation" or a mild turn.',typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.17.2",name:"动词“干”表示做/从事",pinyin:"gàn",type:"动词",explainEn:"Use 干 in spoken Chinese to mean “do / work at”.",structure:"干 + 工作/事情；干什么",examples:[{zh:"你在干什么？",en:"What are you doing?"},{zh:"他在银行干了五年。",en:"He worked at a bank for five years."},{zh:"这件事我来干。",en:"I will do this."}],exercises:[{q:"填空：你在___什么？",a:"干",instr:"填空",instrEn:"Fill in the blank",body:"你在___什么？"},{q:"翻译：I will do this.",a:"这件事我来干。",instr:"翻译",instrEn:"Translate",body:"I will do this."},{q:"选择：口语“do a job”可用（干 / 因此）。",a:"干",instr:"选择",instrEn:"Choose",body:"口语“do a job”可用（干 / 因此）。"}],note:"很口语，具体意思由宾语决定。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Very colloquial; its meaning depends on the object.",typeEn:"Verb",tier:"HSK4教材内"},{id:"4.17.3",name:"动量词“趟”和“次”",pinyin:"tàng / cì",type:"动量词",explainEn:"次 counts actions generally. 趟 counts a trip from one place to another.",structure:"V + 数字 + 次；去/跑 + 数字 + 趟",examples:[{zh:"我去过北京三次。",en:"I have been to Beijing three times."},{zh:"我今天跑了两趟银行。",en:"I made two trips to the bank today."},{zh:"这个电影我看了两次。",en:"I watched this movie twice."}],exercises:[{q:"填空：我去银行跑了两___。",a:"趟",instr:"填空",instrEn:"Fill in the blank",body:"我去银行跑了两___。"},{q:"填空：这个电影看了三___。",a:"次",instr:"填空",instrEn:"Fill in the blank",body:"这个电影看了三___。"},{q:"翻译：I went there twice.",a:"我去了两次。",instr:"翻译",instrEn:"Translate",body:"I went there twice."}],note:"“趟”强调来回/去一处的行程；“次”适用范围更广。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"趟 stresses a trip to and from a place; 次 is broader.",typeEn:"Verbal measure word",tier:"HSK4教材内"},{id:"4.17.4",name:"为了……而……",pinyin:"wèile ... ér ...",type:"目的结构",explainEn:"Use 为了…而… to mean “for the sake of / in order to…”.",structure:"为了 + 目的，而 + 行动",examples:[{zh:"他为了健康而每天运动。",en:"He exercises every day for his health."},{zh:"我们为了这个目标而努力。",en:"We work hard for this goal."},{zh:"她为了学习汉语而来到中国。",en:"She came to China to study Chinese."}],exercises:[{q:"填空：他___健康___运动。",a:"为了；而",instr:"填空",instrEn:"Fill in the blank",body:"他___健康___运动。"},{q:"翻译：We work hard for this goal.",a:"我们为了这个目标而努力。",instr:"翻译",instrEn:"Translate",body:"We work hard for this goal."},{q:"连接：学习汉语。她来到中国。",a:"她为了学习汉语而来到中国。",instr:"连接",instrEn:"Join the sentences",body:"学习汉语。她来到中国。"}],note:"“而”有时可以省略；完整结构更正式。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"而 can sometimes be dropped; the full pattern is more formal.",typeEn:"Purpose structure",tier:"HSK4教材内"},{id:"4.17.5",name:"副词“仍然”",pinyin:"réngrán",type:"副词",explainEn:"Use 仍然 to mean “still”. It is more formal than 还.",structure:"仍然 + 谓语",examples:[{zh:"虽然很累，他仍然继续工作。",en:"Although he was tired, he still kept working."},{zh:"下雨了，比赛仍然继续。",en:"It rained, but the game still continued."},{zh:"很多年过去了，这里仍然很漂亮。",en:"Many years passed, and this place is still beautiful."}],exercises:[{q:"填空：很晚了，他___在工作。",a:"仍然",instr:"填空",instrEn:"Fill in the blank",body:"很晚了，他___在工作。"},{q:"翻译：The game still continued.",a:"比赛仍然继续。",instr:"翻译",instrEn:"Translate",body:"The game still continued."},{q:"选择：较书面的“still”用（仍然 / 偶尔）。",a:"仍然",instr:"选择",instrEn:"Choose",body:"较书面的“still”用（仍然 / 偶尔）。"}],note:"“仍然”比“还”正式，常出现在书面语。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"仍然 is more formal than 还 and common in writing.",typeEn:"Adverb",tier:"HSK4教材内"}]},{num:18,title:"科技与世界",points:[{id:"4.18.1",name:"“是否”表示“是不是”",pinyin:"shìfǒu",type:"疑问形式",explainEn:"Use 是否 to mean “whether”. It is more formal than 是不是.",structure:"是否 + 谓语；V + 是否",examples:[{zh:"我不知道他是否会来。",en:"I do not know whether he will come."},{zh:"请确认信息是否正确。",en:"Please confirm whether the information is correct."},{zh:"我们还没决定是否参加。",en:"We have not decided whether to join."}],exercises:[{q:"填空：我不知道他___会来。",a:"是否",instr:"填空",instrEn:"Fill in the blank",body:"我不知道他___会来。"},{q:"翻译：Please confirm whether it is correct.",a:"请确认是否正确。",instr:"翻译",instrEn:"Translate",body:"Please confirm whether it is correct."},{q:"把“是不是参加”改成较正式形式。",a:"是否参加"}],note:"多用于书面语、间接疑问句。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Mostly used in writing and indirect questions.",typeEn:"Question form",tier:"HSK4教材内"},{id:"4.18.2",name:"“受不了 / 受得了”",pinyin:"shòubuliǎo / shòudeliǎo",type:"可能补语",explainEn:"Use 受不了 for “cannot stand / cannot bear”. 受得了 means “can bear it”.",structure:"受得了 / 受不了 + 名词/情况",examples:[{zh:"天气太热，我受不了了。",en:"It is too hot; I cannot stand it."},{zh:"这么大的声音谁受得了？",en:"Who can stand such a loud noise?"},{zh:"我受不了每天睡这么晚。",en:"I cannot stand sleeping so late every day."}],exercises:[{q:"填空：太吵了，我___。",a:"受不了",instr:"填空",instrEn:"Fill in the blank",body:"太吵了，我___。"},{q:"翻译：Who can stand this?",a:"谁受得了？",instr:"翻译",instrEn:"Translate",body:"Who can stand this?"},{q:"选择：可以忍受用（受得了 / 受不了）。",a:"受得了",instr:"选择",instrEn:"Choose",body:"可以忍受用（受得了 / 受不了）。"}],note:"表示身体或心理上能不能承受。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Shows whether one can physically or mentally bear it.",typeEn:"Potential compl.",tier:"HSK4教材内"},{id:"4.18.3",name:"“接着”和“然后”",pinyin:"jiēzhe / ránhòu",type:"顺序连接",explainEn:"Both show sequence. 接着 means “next, immediately after”; 然后 simply means “then”.",structure:"先A，接着B，然后C",examples:[{zh:"我先吃饭，接着做作业。",en:"First I eat, then I do homework."},{zh:"他介绍完自己，然后坐下了。",en:"He introduced himself and then sat down."},{zh:"我们先开会，接着去吃饭。",en:"First we have a meeting, then we go eat."}],exercises:[{q:"填空：先洗手，___吃饭。",a:"接着/然后",instr:"填空",instrEn:"Fill in the blank",body:"先洗手，___吃饭。"},{q:"翻译：Then he sat down.",a:"然后他坐下了。",instr:"翻译",instrEn:"Translate",body:"Then he sat down."},{q:"用“接着”连接：开会。去吃饭。",a:"我们先开会，接着去吃饭。",instr:"用“接着”连接",instrEn:"Join with 接着",body:"开会。去吃饭。"}],note:"“接着”更强调紧接前面的动作。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"接着 stresses coming right after the previous action.",typeEn:"Sequence linker",tier:"HSK4教材内"},{id:"4.18.4",name:"“除此以外”表示另外/除了这个",pinyin:"chúcǐ yǐwài",type:"范围结构",explainEn:"Use 除此以外 to mean “besides this / apart from this”.",structure:"前文内容。除此以外，……",examples:[{zh:"这个工作离家近。除此以外，工资也不错。",en:"This job is close to home. Besides this, the salary is good."},{zh:"我会英语。除此以外，我还会一点儿日语。",en:"I speak English. Besides that, I also speak a little Japanese."},{zh:"这里交通方便，除此以外，环境也很好。",en:"Transportation is convenient here; besides, the environment is good."}],exercises:[{q:"填空：工资不错，___，离家也近。",a:"除此以外",instr:"填空",instrEn:"Fill in the blank",body:"工资不错，___，离家也近。"},{q:"翻译：Besides this, the environment is good.",a:"除此以外，环境也很好。",instr:"翻译",instrEn:"Translate",body:"Besides this, the environment is good."},{q:"选择：“besides this”用（除此以外 / 其中）。",a:"除此以外",instr:"选择",instrEn:"Choose",body:"“besides this”用（除此以外 / 其中）。"}],note:"“此”指前面已经说过的内容。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"此 refers to what was just mentioned.",typeEn:"Scope structure",tier:"HSK4教材内"},{id:"4.18.5",name:"“把……叫作……”表示命名",pinyin:"bǎ ... jiàozuò ...",type:"把字句",explainEn:"Use 把 A 叫作 B to mean “call A B / name A B”.",structure:"把 + A + 叫作 + B",examples:[{zh:"我们把这种方法叫作“新办法”。",en:"We call this method the “new method”."},{zh:"人们把他叫作王老师。",en:"People call him Teacher Wang."},{zh:"我们把这一天叫作“家庭日”。",en:"We call this day “Family Day”."}],exercises:[{q:"填空：我们___这种方法___新办法。",a:"把；叫作",instr:"填空",instrEn:"Fill in the blank",body:"我们___这种方法___新办法。"},{q:"翻译：People call him Teacher Wang.",a:"人们把他叫作王老师。",instr:"翻译",instrEn:"Translate",body:"People call him Teacher Wang."},{q:"排序：把 / 我们 / 这一天 / 家庭日 / 叫作",a:"我们把这一天叫作家庭日。",instr:"排序",instrEn:"Reorder the words",body:"把 / 我们 / 这一天 / 家庭日 / 叫作"}],note:"表示给人、事物或概念一个名称。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Gives a name to a person, thing or concept.",typeEn:"把 sentence",tier:"HSK4教材内"}]},{num:19,title:"生活的味道",points:[{id:"4.19.1",name:"省略“不管/无论”的任指结构",pinyin:"shěnglüè bùguǎn/wúlùn",type:"条件结构",explainEn:"Sometimes 不管/无论 can be omitted when a question-word pattern already means “no matter…”.",structure:"疑问代词 + 都/也 + 结果",examples:[{zh:"谁来我都欢迎。",en:"Whoever comes, I welcome them."},{zh:"你去哪儿我都跟你去。",en:"Wherever you go, I will go with you."},{zh:"什么时候开始都可以。",en:"Any time is fine to start."}],exercises:[{q:"填空：___来我都欢迎。",a:"谁",instr:"填空",instrEn:"Fill in the blank",body:"___来我都欢迎。"},{q:"翻译：Wherever you go, I will go with you.",a:"你去哪儿我都跟你去。",instr:"翻译",instrEn:"Translate",body:"Wherever you go, I will go with you."},{q:"补全：___开始都可以。",a:"什么时候",instr:"补全",instrEn:"Complete the sentence",body:"___开始都可以。"}],note:"前面其实可以理解为省略了“不管/无论”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The first part can be read as omitting 不管/无论.",typeEn:"Conditional structure",tier:"HSK4教材内"},{id:"4.19.2",name:"趋向/结果用法“上”",pinyin:"shàng",type:"补语/动词",explainEn:"上 after a verb can show attaching, reaching, or starting a state.",structure:"V + 上",examples:[{zh:"请关上门。",en:"Please close the door."},{zh:"他终于找上工作了。",en:"He finally found a job."},{zh:"我喜欢上这个城市了。",en:"I came to like this city."}],exercises:[{q:"填空：请关___门。",a:"上",instr:"填空",instrEn:"Fill in the blank",body:"请关___门。"},{q:"翻译：I came to like this city.",a:"我喜欢上这个城市了。",instr:"翻译",instrEn:"Translate",body:"I came to like this city."},{q:"选择：“start to like”常说“喜欢（上 / 下）”。",a:"上",instr:"选择",instrEn:"Choose",body:"“start to like”常说“喜欢（上 / 下）”。"}],note:"“上”除了方向，还能表示动作达到结果或进入一种新状态。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Besides direction, 上 can mark reaching a result or entering a new state.",typeEn:"Complement / Verb",tier:"HSK4教材内"},{id:"4.19.3",name:"趋向补语“出来”的引申义",pinyin:"chūlái",type:"趋向补语引申",explainEn:"V + 出来 can mean a result becomes clear, visible, or recognized.",structure:"V + 出来",examples:[{zh:"我看出来他很累。",en:"I can tell that he is tired."},{zh:"你听出来是谁了吗？",en:"Could you tell who it was by listening?"},{zh:"他终于想出来一个办法。",en:"He finally came up with a solution."}],exercises:[{q:"填空：我看___他不高兴。",a:"出来",instr:"填空",instrEn:"Fill in the blank",body:"我看___他不高兴。"},{q:"翻译：He came up with a solution.",a:"他想出来一个办法。",instr:"翻译",instrEn:"Translate",body:"He came up with a solution."},{q:"选择：表示“认出来”用（看出来 / 看下来）。",a:"看出来",instr:"选择",instrEn:"Choose",body:"表示“认出来”用（看出来 / 看下来）。"}],note:"常见引申：看出来、听出来、想出来、说出来。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Common extensions: 看出来, 听出来, 想出来, 说出来.",typeEn:"Directional (fig.)",tier:"HSK4教材内"},{id:"4.19.4",name:"固定表达“总的来说”",pinyin:"zǒng de láishuō",type:"总结表达",explainEn:"Use 总的来说 to mean “generally speaking / overall”.",structure:"总的来说，+ 总结",examples:[{zh:"总的来说，这次旅行很顺利。",en:"Overall, this trip went smoothly."},{zh:"总的来说，他做得不错。",en:"Generally speaking, he did well."},{zh:"总的来说，这个办法比较简单。",en:"Overall, this method is relatively simple."}],exercises:[{q:"填空：___，这次活动很成功。",a:"总的来说",instr:"填空",instrEn:"Fill in the blank",body:"___，这次活动很成功。"},{q:"翻译：Overall, he did well.",a:"总的来说，他做得不错。",instr:"翻译",instrEn:"Translate",body:"Overall, he did well."},{q:"选择：“overall”用（总的来说 / 拿来说）。",a:"总的来说",instr:"选择",instrEn:"Choose",body:"“overall”用（总的来说 / 拿来说）。"}],note:"常放在总结句的开头。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Usually opens a summarizing sentence.",typeEn:"Summary expression",tier:"HSK4教材内"},{id:"4.19.5",name:"“在于”表示关键/原因在某处",pinyin:"zàiyú",type:"动词",explainEn:"Use 在于 to mean “lie in / depend on”.",structure:"关键/问题/原因 + 在于 + 内容",examples:[{zh:"成功在于坚持。",en:"Success lies in persistence."},{zh:"问题在于时间不够。",en:"The problem is that there is not enough time."},{zh:"学习语言的关键在于多练习。",en:"The key to language learning lies in practice."}],exercises:[{q:"填空：问题___时间不够。",a:"在于",instr:"填空",instrEn:"Fill in the blank",body:"问题___时间不够。"},{q:"翻译：Success lies in persistence.",a:"成功在于坚持。",instr:"翻译",instrEn:"Translate",body:"Success lies in persistence."},{q:"排序：在于 / 关键 / 多练习 / 学习",a:"学习的关键在于多练习。",instr:"排序",instrEn:"Reorder the words",body:"在于 / 关键 / 多练习 / 学习"}],note:"常和“问题、关键、原因、区别”等词搭配。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Often pairs with 问题/关键/原因/区别.",typeEn:"Verb",tier:"HSK4教材内"}]},{num:20,title:"路上的风景",points:[{id:"4.20.1",name:"“V着V着……”表示动作进行中出现变化",pinyin:"V-zhe V-zhe",type:"进行结构",explainEn:"Use V着V着… when something happens while an action is continuing.",structure:"V着V着，+ 新情况",examples:[{zh:"他走着走着，突然停下来了。",en:"He was walking when he suddenly stopped."},{zh:"我看着看着就睡着了。",en:"I fell asleep while watching."},{zh:"我们聊着聊着就忘了时间。",en:"We were chatting and forgot the time."}],exercises:[{q:"填空：他走___走___，突然停了。",a:"着；着",instr:"填空",instrEn:"Fill in the blank",body:"他走___走___，突然停了。"},{q:"翻译：I fell asleep while watching.",a:"我看着看着就睡着了。",instr:"翻译",instrEn:"Translate",body:"I fell asleep while watching."},{q:"用“聊着聊着”造句。",a:"我们聊着聊着忘了时间。"}],note:"表示一个动作持续一段时间后发生新的情况。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Shows a new situation arising after an action goes on for a while.",typeEn:"Progressive structure",tier:"HSK4教材内"},{id:"4.20.2",name:"“一……就……”表示一发生就马上……",pinyin:"yī ... jiù ...",type:"承接结构",explainEn:"Use 一…就… for “as soon as…”.",structure:"一 + V1，就 + V2",examples:[{zh:"我一到家就给你打电话。",en:"I will call you as soon as I get home."},{zh:"他一听就明白了。",en:"He understood as soon as he heard it."},{zh:"孩子一看到妈妈就笑了。",en:"The child smiled as soon as he saw Mom."}],exercises:[{q:"填空：我___到家___给你打电话。",a:"一；就",instr:"填空",instrEn:"Fill in the blank",body:"我___到家___给你打电话。"},{q:"翻译：He understood as soon as he heard it.",a:"他一听就明白了。",instr:"翻译",instrEn:"Translate",body:"He understood as soon as he heard it."},{q:"连接：他看到老师。他站起来了。",a:"他一看到老师就站起来了。",instr:"连接",instrEn:"Join the sentences",body:"他看到老师。他站起来了。"}],note:"两个动作相隔时间很短。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The two actions are only a very short time apart.",typeEn:"Sequential structure",tier:"HSK4教材内"},{id:"4.20.3",name:"“究竟”和“到底”",pinyin:"jiūjìng / dàodǐ",type:"副词",explainEn:"Both mean “exactly / after all” in strong questions. 究竟 is a little more formal.",structure:"究竟/到底 + 疑问句",examples:[{zh:"你究竟想要什么？",en:"What exactly do you want?"},{zh:"他到底去哪儿了？",en:"Where on earth did he go?"},{zh:"这件事究竟是谁做的？",en:"Who exactly did this?"}],exercises:[{q:"填空：你___想说什么？",a:"究竟/到底",instr:"填空",instrEn:"Fill in the blank",body:"你___想说什么？"},{q:"翻译：Who exactly did this?",a:"这件事究竟是谁做的？",instr:"翻译",instrEn:"Translate",body:"Who exactly did this?"},{q:"选择：较书面的“exactly”可用（究竟 / 偶尔）。",a:"究竟",instr:"选择",instrEn:"Choose",body:"较书面的“exactly”可用（究竟 / 偶尔）。"}],note:"两者意思很接近；“到底”口语更常见。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"The two are very close; 到底 is more common in speech.",typeEn:"Adverb",tier:"HSK4教材内"},{id:"4.20.4",name:"“起来”表示开始/总体感觉",pinyin:"qǐlái",type:"趋向补语引申",explainEn:"V/Adj + 起来 can mean “start to…” or “when you look/listen/taste…”.",structure:"V + 起来；看/听/吃 + 起来 + 评价",examples:[{zh:"天冷起来了。",en:"It has started to get cold."},{zh:"这件衣服看起来不错。",en:"This clothing looks good."},{zh:"这个菜吃起来有点儿甜。",en:"This dish tastes a little sweet."}],exercises:[{q:"填空：天气冷___了。",a:"起来",instr:"填空",instrEn:"Fill in the blank",body:"天气冷___了。"},{q:"翻译：This clothing looks good.",a:"这件衣服看起来不错。",instr:"翻译",instrEn:"Translate",body:"This clothing looks good."},{q:"选择：“tastes sweet”可说“吃（起来 / 出来）很甜”。",a:"起来",instr:"选择",instrEn:"Choose",body:"“tastes sweet”可说“吃（起来 / 出来）很甜”。"}],note:"常见：看起来、听起来、吃起来，以及“天气冷起来了”。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Common: 看起来, 听起来, 吃起来, and 天气冷起来了.",typeEn:"Directional (fig.)",tier:"HSK4教材内"},{id:"4.20.5",name:"“V起……”表示提起某话题/开始说到",pinyin:"V qǐ ...",type:"补语/固定结构",explainEn:"Use V + 起 + topic to mean “when it comes to / start talking about…”.",structure:"说起/谈起/提起 + 人或事",examples:[{zh:"说起旅游，我最喜欢北京。",en:"Speaking of travel, I like Beijing best."},{zh:"谈起工作，他有很多话要说。",en:"When it comes to work, he has a lot to say."},{zh:"提起这件事，我就想笑。",en:"When this is mentioned, I want to laugh."}],exercises:[{q:"填空：___起旅游，我想去云南。",a:"说",instr:"填空",instrEn:"Fill in the blank",body:"___起旅游，我想去云南。"},{q:"翻译：Speaking of work, he has a lot to say.",a:"谈起工作，他有很多话要说。",instr:"翻译",instrEn:"Translate",body:"Speaking of work, he has a lot to say."},{q:"选择：“when this is mentioned”可用（提起 / 提出）这件事。",a:"提起",instr:"选择",instrEn:"Choose",body:"“when this is mentioned”可用（提起 / 提出）这件事。"}],note:"常见固定搭配：说起、谈起、提起。",source:"https://courses.chinesezerotohero.com/p/hsk-4-course",noteEn:"Common fixed pairings: 说起, 谈起, 提起.",typeEn:"Complement / Fixed",tier:"HSK4教材内"}]}],s={series:e,unit:4,lessons:n};export{s as default,n as lessons,e as series,t as unit};
